-- ============================================================================
-- Dictionnaire en base (ADR 0022, décidé par David le 2026-10-10)
-- ============================================================================
--
-- Le dictionnaire (mots mathématiques, définitions par niveau, synonymes, formes,
-- étiquettes de sens, filières partagées) quitte src/lib/data/math-dictionary-fr.ts
-- pour la base ; l'admin le modifie depuis /dashboard/admin/dictionnaire.
--
-- Accès tranché par David (2026-10-10, question Q2) :
--   - lecture par TOUS, visiteurs compris, des entrées non masquées (c'est déjà le
--     cas : le fichier est dans le code envoyé au navigateur) ;
--   - modification par l'admin seul (is_admin()), sans suppression : une entrée se
--     masque (un renvoi ou un marquage {.def=…} peut la viser) ;
--   - historique (version précédente à chaque modification) lisible par l'admin seul.
-- Aucun accès en lecture nouveau.
--
-- Additive. Rollback :
--   drop table public.dictionary_entry_versions;
--   drop table public.dictionary_entries;
--   drop function public.dictionary_entries_keep_version();

-- ============================================================================
-- 1. Tables
-- ============================================================================

create table public.dictionary_entries (
	id uuid primary key default gen_random_uuid(),
	-- Ordre du fichier d'origine : un renvoi vise le premier terme principal de son nom
	position integer not null,
	term text not null check (length(trim(term)) > 0),
	sense text check (sense is null or length(trim(sense)) > 0),
	grade text not null check (grade in ('CP', 'CE1', 'CE2', 'CM1', 'CM2', '6', '5', '4', '3', '2', '1_GEN', 'T_GEN', '1_SPE', 'T_SPE', 'T_EXP', 'T_COMP', '1_TECHNO', 'T_TECHNO')),
	tags text[] not null default '{}',
	-- { mode?, items: [{ grade, content, sharedWith? }] } (GradedField)
	definitions jsonb,
	exemples jsonb,
	history text,
	-- Chemin relatif au site seulement : pas d'URL externe (pistage des visiteurs)
	image text check (image is null or image ~ '^/[A-Za-z0-9/_.-]+$'),
	synonyms text[] not null default '{}',
	forms text[] not null default '{}',
	auto_link boolean not null default true,
	derived_from text,
	-- Lien « Voir aussi » du glossaire : pages du Cabinet Noir seulement (jamais javascript:…)
	see_also jsonb check (
		see_also is null
		or (see_also->>'path') ~ '^/chiffrement(/[a-z]+)?$'
	),
	shared_with text[] not null default '{}',
	hidden boolean not null default false,
	created_at timestamptz not null default now(),
	updated_at timestamptz not null default now(),
	updated_by uuid references auth.users (id) on delete set null
);

comment on table public.dictionary_entries is
	'Dictionnaire mathématique (ADR 0022) : une entrée par mot et par sens. Lecture publique des entrées non masquées, écriture admin.';

-- Un nom et un sens par entrée (les règles complètes, accents compris, sont vérifiées à l'enregistrement)
create unique index dictionary_entries_term_sense
	on public.dictionary_entries (term, coalesce(sense, ''));
create index dictionary_entries_position on public.dictionary_entries (position);

create table public.dictionary_entry_versions (
	id uuid primary key default gen_random_uuid(),
	entry_id uuid not null references public.dictionary_entries (id) on delete cascade,
	-- L'entrée telle qu'elle était AVANT la modification
	entry jsonb not null,
	saved_at timestamptz not null default now(),
	saved_by uuid references auth.users (id) on delete set null
);

create index dictionary_entry_versions_entry
	on public.dictionary_entry_versions (entry_id, saved_at desc);

-- ============================================================================
-- 2. Historique : chaque modification garde la version précédente
-- ============================================================================
-- Droits de l'appelant (pas SECURITY DEFINER) : l'admin a le droit d'insérer
-- dans l'historique (policy ci-dessous), personne d'autre ne modifie une entrée.
-- L'auteur et les dates sont posés ici, jamais par l'appelant.

create function public.dictionary_entries_keep_version()
returns trigger
language plpgsql
set search_path = ''
as $$
begin
	if tg_op = 'UPDATE' then
		insert into public.dictionary_entry_versions (entry_id, entry, saved_by)
		values (old.id, to_jsonb(old), auth.uid());
		new.created_at := old.created_at;
	else
		new.created_at := now();
	end if;
	new.updated_at := now();
	new.updated_by := auth.uid();
	return new;
end;
$$;

create trigger dictionary_entries_keep_version
	before insert or update on public.dictionary_entries
	for each row execute function public.dictionary_entries_keep_version();

-- ============================================================================
-- 3. Droits de table
-- ============================================================================
-- Les privilèges par défaut donnent tout à anon et authenticated : on repart de
-- zéro. anon lit seulement ; authenticated lit et écrit, filtré par la RLS ;
-- personne ne supprime (pas de DELETE accordé : 42501).

revoke all on public.dictionary_entries, public.dictionary_entry_versions from anon, authenticated;
grant select on public.dictionary_entries to anon;
grant select, insert, update on public.dictionary_entries to authenticated;
grant select, insert on public.dictionary_entry_versions to authenticated;

revoke execute on function public.dictionary_entries_keep_version() from public, anon, authenticated;

-- ============================================================================
-- 4. RLS
-- ============================================================================

alter table public.dictionary_entries enable row level security;
alter table public.dictionary_entry_versions enable row level security;

-- Deux policies de lecture (OU) : les entrées masquées pour l'admin seul ;
-- is_admin() n'est appelé que pour authenticated, une fois par requête (select …)
create policy "Anyone can read visible dictionary entries"
	on public.dictionary_entries for select
	to anon, authenticated
	using (not hidden);

create policy "Admins can read hidden dictionary entries"
	on public.dictionary_entries for select
	to authenticated
	using ((select public.is_admin()));

create policy "Admins can insert dictionary entries"
	on public.dictionary_entries for insert
	to authenticated
	with check ((select public.is_admin()));

create policy "Admins can update dictionary entries"
	on public.dictionary_entries for update
	to authenticated
	using ((select public.is_admin()))
	with check ((select public.is_admin()));

create policy "Admins can read dictionary history"
	on public.dictionary_entry_versions for select
	to authenticated
	using ((select public.is_admin()));

-- Une version porte toujours l'auteur réel : pas de faux historique, même par l'admin
create policy "Admins can write dictionary history"
	on public.dictionary_entry_versions for insert
	to authenticated
	with check ((select public.is_admin()) and saved_by = (select auth.uid()));

