CE1","content":"Nombre situé sous la barre de fraction. Dans $\\frac{3}{4}$, le dénominateur est $4$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":95,"term":"fraction irréductible","sense":null,"grade":"3","tags":["fractions","arithmétique"],"definitions":{"items":[{"grade":"3","content":"Fraction dont le numérateur et le dénominateur n'ont pas de diviseur commun autre que $1$. Ex : $\\frac{3}{4}$ est irréductible."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":96,"term":"simplifier une fraction","sense":null,"grade":"4","tags":["fractions","arithmétique"],"definitions":{"items":[{"grade":"4","content":"Diviser le numérateur et le dénominateur par un même nombre entier, diviseur des deux : $\\frac{6}{8} = \\frac{3}{4}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":97,"term":"fractions égales","sense":null,"grade":"CE2","tags":["fractions"],"definitions":{"items":[{"grade":"CE2","content":"Deux fractions sont égales si elles représentent le même nombre. Ex : $\\frac{1}{2} = \\frac{2}{4}$."}]},"exemples":null,"history":null,"image":null,"synonyms":["fractions équivalentes"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":98,"term":"mise au même dénominateur","sense":null,"grade":"CM2","tags":["fractions"],"definitions":{"items":[{"grade":"CM2","content":"Transformer des fractions pour qu'elles aient le même dénominateur, afin de les comparer ou les additionner."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":99,"term":"inverse","sense":null,"grade":"4","tags":["fractions","operations"],"defin