rade":"5","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Transformer un produit en somme en utilisant la distributivité. Ex : $3(x + 2) = 3x + 6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["développe","développez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":120,"term":"factoriser","sense":null,"grade":"5","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Écrire sous forme d'un produit : une somme, $3x + 6 = 3(x + 2)$, ou un nombre entier, $21 = 3 \\times 7$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["factorise","factorisez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":121,"term":"réduire","sense":null,"grade":"5","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Regrouper les termes semblables dans une expression. Ex : $3x + 2x = 5x$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["réduis","réduisez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":122,"term":"distributivité","sense":null,"grade":"CM1","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"CM1","content":"Propriété qui permet de calculer un produit en le découpant. Ex : $7 \\times 12 = 7 \\times 10 + 7 \\times 2 = 70 + 14 = 84$."},{"grade":"5","content":"Propriété : $a(b + c) = ab + ac$. Permet de développer ou factoriser."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":123,"term":"identité remarquable","sense":null,"grade":"3","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"3","content":"Chacune des trois égalités vraies pour tous nombres $a$ et $b$ : $(a+b)^2 = a^2 + 2ab + b^2$, $(a-b)^2 = a^2 - 2ab + b^2$ et $(a-b)(a+b) = a^2 - b^2$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":124,"term":"coefficient","sense":null,"grade":"5","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Nombre qui multiplie : dans $5x$, le coefficient de $x$ est $5$."},{"grade":"3","content":"Les coefficients de la fonction affine $x \\mapsto ax + b$ sont les nombres $a$ et $b$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":125,"term":"monôme","sense":null,"grade":"1_SPE","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"1_SPE","content":"Produit d'un nombre par une puissance d'une lettre, comme $3x^2$ ou $-5x$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":126,"term":"polynôme","sense":null,"grade":"1_SPE","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"1_SPE","content":"Expression comme $ax^2 + bx + c$ ou $ax^3 + bx^2 + cx + d$ : une somme de termes « nombre × puissance de $x$ ». Le plus grand exposant de coefficient non nul est son degré : $2x^2 + 3x - 1$ est de degré $2$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":127,"term":"degré","sense":"équation","grade":"4","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"4","content":"Une équation du premier degré est une équation où l'inconnue n'est jamais élevée au carré ni à une autre puissance. Ex : $3x + 2 = 8$."},{"grade":"1_SPE","content":"Plus grand exposant de $x$ dont le coefficient n'est pas nul : $2x^3 + x$ est de degré $3$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared