25,"term":"taux de variation","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"$\\frac{f(b) - f(a)}{b - a}$ : variation moyenne de $f$ entre $a$ et $b$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":["taux d'accroissement"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":226,"term":"extremum","sense":null,"grade":"2","tags":["fonctions"],"definitions":{"items":[{"grade":"2","content":"Le plus grand (maximum) ou le plus petit (minimum) des nombres $f(x)$ quand $x$ parcourt un intervalle."}]},"exemples":null,"history":null,"image":null,"synonyms":["extrema"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":227,"term":"fonction exponentielle","sense":"exp","grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Fonction $f(x) = e^x$ ($\\exp(x)$). Seule fonction égale à sa propre dérivée avec $f(0) = 1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":228,"term":"fonction logarithme","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Fonction $\\ln(x)$ définie pour $x > 0$. Réciproque de l'exponentielle : $\\ln(e^x) = x$."}]},"exemples":null,"history":null,"image":null,"synonyms":["logarithme népérien"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":229,"term":"intervalle","sense":null,"grade":"2","tags":["fonctions"],"definitions":{"items":[{"grade":"2","content":"Ensemble des réels $x$ qui vérifient une ou deux inégalités : $[2 ; 5]$ contient les $x$ tels que $2 \\leq x \\leq 5$ ; $]-\\infty ; 3[$ contient les $x$ tels que $x < 3$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived