sition":236,"term":"intégrale","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Pour $f$ continue et positive sur $[a ; b]$, $\\int_a^b f(x)\\,\\mathrm{d}x$ est l'aire du domaine compris entre la courbe de $f$, l'axe des abscisses et les droites d'équations $x = a$ et $x = b$. Pour $f$ continue de signe quelconque, c'est $F(b) - F(a)$, où $F$ est une primitive de $f$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":237,"term":"intégrer","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":null,"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":"intégrale","see_also":null,"shared_with":[]},{"position":238,"term":"limite","sense":null,"grade":"1_SPE","tags":["fonctions","suites"],"definitions":{"items":[{"grade":"1_SPE","content":"Une suite a pour limite le réel $\\ell$ si ses termes deviennent aussi proches de $\\ell$ que l'on veut quand $n$ est assez grand ; elle a pour limite $+\\infty$ si ses termes deviennent aussi grands que l'on veut."},{"grade":"T_SPE","content":"Le réel $\\ell$ est la limite de $(u_n)$ si tout intervalle ouvert contenant $\\ell$ contient tous les termes $u_n$ à partir d'un certain rang ; même idée pour $f(x)$ quand $x$ tend vers $a$ ou vers $+\\infty$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":239,"term":"logarithme","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Fonction réciproque de l'exponentielle. $\\ln(e^x) = x$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":240,"term":"coordonnée","sense":null,"grade":"5","tags":["géométrie","fonctions"],"definitions":{"items":[{"grade":"5","content":"Nombre repérant la position d'un point sur un axe ou dans un plan."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":241,"term":"suite","sense":null,"grade":"CP","tags":["suites"],"definitions":{"items":[{"grade":"CP","content":"Liste d'objets, de formes ou de nombres rangés les uns après les autres, souvent selon une règle. Ex : $2$, $4$, $6$, $8$… (on ajoute $2$ à chaque fois)."},{"grade":"1_SPE","content":"Fonction de $\\mathbb{N}$ dans $\\mathbb{R}$. Liste ordonnée de nombres : $u_0, u_1, u_2, \\ldots$","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":["suite numérique"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":242,"term":"terme","sense":"suite","grade":"CM1","tags":["suites"],"definitions":{"items":[{"grade":"CM1","content":"Chacun des nombres d'une suite. Ex : dans la suite $3$, $6$, $9$, $12$…, le deuxième terme est $6$."},{"grade":"1_SPE","content":"Élément d'une suite. $u_n$ est le terme de rang $n$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":243,"term":"rang","sense":null,"grade":"CP","tags":["suites"],"definitions":{"items":[{"grade":"CP","content":"Place occupée dans une file ou une liste : premier, deuxième, troisième… Ex : Léa est au troisième rang de la file."},{"grade":"6","content":"Le rang d'un chiffre est sa place dans l'écriture d'un nombre : dans $3{,}52$, le chiffre $5$ est au rang des dixièmes."},{"grade":"1_SPE","content":"Indice d'un terme dans une suite. Dans $u_5$, le rang est $5$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]}