ie","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Transformation qui agrandit ou réduit une figure par rapport à un centre et un rapport $k$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":289,"term":"théorème de Pythagore","sense":null,"grade":"4","tags":["géométrie"],"definitions":{"items":[{"grade":"4","content":"Dans un triangle rectangle, $c^2 = a^2 + b^2$ où $c$ est l'hypoténuse."}]},"exemples":null,"history":null,"image":null,"synonyms":["Pythagore"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":290,"term":"théorème de Thalès","sense":null,"grade":"3","tags":["géométrie","proportionnalité"],"definitions":{"items":[{"grade":"3","content":"Si deux droites sécantes en $A$ sont coupées par deux droites parallèles $(BC)$ et $(MN)$, avec $B$ et $M$ sur l'une, $C$ et $N$ sur l'autre, alors $\\frac{AM}{AB} = \\frac{AN}{AC} = \\frac{MN}{BC}$."}]},"exemples":null,"history":null,"image":null,"synonyms":["Thalès"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":291,"term":"hypoténuse","sense":null,"grade":"4","tags":["géométrie"],"definitions":{"items":[{"grade":"4","content":"Côté le plus long d'un triangle rectangle, opposé à l'angle droit."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":292,"term":"trigonométrie","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Étude des relations entre les angles et les côtés d'un triangle. Utilise $\\cos$, $\\sin$, $\\tan$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":293,"term":"cosinus","sense":null,"grade":"3","tags":["géomé