rie"],"definitions":{"items":[{"grade":"CE2","content":"Dans une pyramide, la face sur laquelle elle est posée, qui n'est pas forcément un triangle. Un prisme ou un cylindre a deux bases, parallèles et superposables."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":399,"term":"base","sense":"vecteurs","grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Une base du plan est formée de deux vecteurs non colinéaires $\\vec{i}$ et $\\vec{j}$ ; elle est orthonormée si ces vecteurs sont orthogonaux et de norme $1$."},{"grade":"T_SPE","content":"Une base de l'espace est formée de trois vecteurs non coplanaires $\\vec{i}$, $\\vec{j}$, $\\vec{k}$ : tout vecteur s'écrit d'une seule façon $x\\vec{i} + y\\vec{j} + z\\vec{k}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":400,"term":"racine","sense":"polynôme","grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Une racine d'un polynôme $P$ est un nombre $a$ tel que $P(a) = 0$. Ainsi, $2$ est une racine de $x^2 - 4$, car $2^2 - 4 = 0$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":401,"term":"échelle","sense":"axe gradué","grade":"CE2","tags":["statistiques","grandeurs"],"definitions":{"items":[{"grade":"CE2","content":"Sur un axe gradué ou un diagramme, ce que représente l'écart entre deux graduations : par exemple, $1$ carreau pour $10$ élèves."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":402,"term":"image","sense":"transformation","grade":"4","tags":["géométrie"],"definitions":{"items":[{"grade":"4","content":"L'image d'un point par une transformation (symétrie, translation…) est le point sur lequel elle l'envoie : par la symétrie de centre $O$, l'image de $M$ est le point $M'$ tel que $O$ soit le milieu de $[MM']$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":403,"term":"complémentaire","sense":"ensemble","grade":"4","tags":["logique","probabilités"],"definitions":{"items":[{"grade":"4","content":"Le complémentaire d'un ensemble $A$ est l'ensemble des éléments qui ne sont pas dans $A$ : pour un dé, le complémentaire de « obtenir un nombre pair » est « obtenir un nombre impair »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":404,"term":"plan","sense":"lieu","grade":"CP","tags":["géométrie"],"definitions":{"items":[{"grade":"CP","content":"Dessin d'un lieu vu de dessus, qui aide à se repérer : le plan de la classe, le plan du quartier."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":405,"term":"série statistique","sense":null,"grade":"5","tags":["statistiques"],"definitions":{"items":[{"grade":"5","content":"Liste des valeurs relevées dans une enquête ou une expérience : les notes d'une classe, les tailles des élèves…"}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":406,"term":"fonction paire","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Une fonction $f$ est paire si, pour tout $x$ de son ensemble de définition, $-x$ en fait aussi partie et $f(-x) = f(x)$ : sa courbe est symétrique par rapport à l'axe des ordonnées. Ex : $x \\mapsto x^2$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":407,"term":"fonction impaire","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Une fonction $f$ est impaire si, pour tout $x$ de son ensemble de définition, $-x$ en fait aussi partie et $f(-x) = -f(x)$ : sa courbe est symétrique par rapport à l'origine. Ex : $x \\mapsto x^3$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":408,"term":"fonction réciproque","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Quand une fonction $f$ associe à chaque $x$ d'un intervalle un nombre $y$, et que chaque $y$ vient d'un seul $x$, la fonction réciproque fait le chemin inverse : elle associe $x$ à $y$. Ex : $\\ln$ est la réciproque de $\\exp$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":409,"term":"impossible","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'un évènement qui ne peut jamais se produire : obtenir $7$ en lançant un dé à six faces."},{"grade":"6","content":"Un évènement impossible a une probabilité égale à $0$."}]},"exemples":null,"history":null,"image":null,"synonyms":["évènement impossible","événement impossible"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":410,"term":"possible","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'un évènement qui peut se produire, sans que ce soit sûr : obtenir $6$ en lançant un dé."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":411,"term":"certain","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'un évènement qui se produit à coup sûr : obtenir un nombre plus petit que $7$ en lançant un dé à six faces."},{"grade":"6","content":"Un évènement certain a une probabilité égale à $1$."}]},"exemples":null,"history":null,"image":null,"synonyms":["évènement certain","événement certain"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":412,"term":"probable","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'un évènement qui a beaucoup de chances de se produire : en lançant un dé, obtenir un nombre plus grand que $1$ est probable."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":413,"term":"peu probable","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'un évènement qui a peu de chances de se produire : tirer la seule boule rouge d'un sac qui contient aussi $20$ boules bleues."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":414,"term":"une chance sur deux","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Un évènement a une chance sur deux de se produire quand il a autant de chances de se produire que de ne pas se produire : obtenir pile en lançant une pièce."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":415,"term":"compris entre","sense":null,"grade":"CE1","tags":["entiers","transversal"],"definitions":{"items":[{"grade":"CE1","content":"Un nombre est compris entre deux nombres s'il est plus