],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":440,"term":"programme de calcul","sense":null,"grade":"CM1","tags":["calcul-littéral","operations"],"definitions":{"items":[{"grade":"CM1","content":"Suite d'instructions de calcul à appliquer à un nombre : « choisis un nombre, multiplie-le par $3$, puis ajoute $5$ »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":441,"term":"algorithme","sense":null,"grade":"CM2","tags":["transversal"],"definitions":{"items":[{"grade":"CM2","content":"Suite d'instructions précises qui permet d'obtenir un résultat ou de résoudre un problème, comme une recette."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":442,"term":"boucle","sense":null,"grade":"5","tags":["transversal"],"definitions":{"items":[{"grade":"5","content":"Partie d'un programme répétée plusieurs fois : un nombre de fois fixé (« répéter $10$ fois ») ou tant qu'une condition est vraie."},{"grade":"2","content":"En Python, une boucle bornée (« for ») répète des instructions un nombre de fois fixé à l'avance : « for k in range(5): » les répète $5$ fois, $k$ prenant les valeurs $0$ à $4$. Une boucle non bornée (« while ») les répète tant qu'une condition est vraie : « while u < 100: »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":443,"term":"instruction conditionnelle","sense":null,"grade":"4","tags":["transversal"],"definitions":{"items":[{"grade":"4","content":"Instruction d'un programme exécutée seulement si une condition est vraie : « si … alors … sinon … »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":444,"term":"million","sense":null,"grade":"CM2","tags":["entiers","numération"],"definitions":{"items":[{"grade":"CM2","content":"Mille milliers : $1\\,000\\,000$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":445,"term":"milliard","sense":null,"grade":"6","tags":["entiers","numération"],"definitions":{"items":[{"grade":"6","content":"Mille millions : $1\\,000\\,000\\,000$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":446,"term":"nombre mixte","sense":null,"grade":"6","tags":["fractions"],"definitions":{"items":[{"grade":"6","content":"Écriture d'un nombre comme un entier plus une fraction plus petite que $1$ : $2 + \\frac{3}{4}$, qui vaut $\\frac{11}{4}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":447,"term":"point d'intersection","sense":null,"grade":"6","tags":["géométrie"],"definitions":{"items":[{"grade":"6","content":"Point commun à deux droites, ou à deux lignes, qui se coupent."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":448,"term":"cercle circonscrit","sense":null,"grade":"6","tags":["géométrie"],"definitions":{"items":[{"grade":"6","content":"Cercle qui passe par les trois sommets d'un triangle ; son centre est le point de rencontre des médiatrices des côtés."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":449,"term":"taux d'évolution","sense":null,"grade":"3","tags":["proportionnalité"],"definitions":{"items":[{"grade":"3","content":"Variation d'une grandeur rapportée à sa valeur de départ, souvent en pourcentage : passer de $50$ à $60$, c'est un taux d'évolution de $\\frac{60 - 50}{50} = 20\\,\\%$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":450,"term":"nombre réel","sense":null,"grade":"2","tags":["transversal"],"definitions":{"items":[{"grade":"2","content":"Nombre qui repère un point sur une droite graduée : les entiers, les décimaux et les fractions, mais aussi $\\sqrt{2}$ ou $\\pi$. Leur ensemble se note $\\mathbb{R}$."}]},"exemples":null,"history":null,"image":null,"synonyms":["réel"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":451,"term":"colinéaire","sense":null,"grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Deux vecteurs sont colinéaires si l'un est égal à l'autre multiplié par un nombre : $\\vec{v} = k\\vec{u}$. Les points $A$, $B$, $C$ sont alignés quand $\\overrightarrow{AB}$ et $\\overrightarrow{AC}$ sont colinéaires."}]},"exemples":null,"history":null,"image":null,"synonyms":["vecteurs colinéaires"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":452,"term":"vecteur directeur","sense":null,"grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Vecteur non nul qui donne la direction d'une droite : $\\overrightarrow{AB}$ est un vecteur directeur de la droite $(AB)$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":453,"term":"déterminant","sense":null,"grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Le déterminant des vecteurs $\\vec{u}(x ; y)$ et $\\vec{v}(x' ; y')$ est le nombre $xy' - x'y$ ; il est nul si et seulement si les deux vecteurs sont colinéaires."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":454,"term":"équation réduite","sense":null,"grade":"2","tags":["fonctions","géométrie"],"definitions":{"items":[{"grade":"2","content":"Une droite non parallèle à l'axe des ordonnées a une équation de la forme $y = mx + p$ : c'est son équation réduite ($m$ est le coefficient directeur, $p$ l'ordonnée à l'origine)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":455,"term":"sens de variation","sense":null,"grade":"2","tags":["fonctions"],"definitions":{"items":[{"grade":"2","content":"Le sens de variation d'une fonction dit sur quels intervalles elle est croissante ou décroissante ; on le résume dans un tableau de variations."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":456,"term":"fonction de référence","sense":null,"grade":"2","tags":["fonctions"],"definitions":{"items":[{"grade":"2","content":"Fonction dont on connaît la courbe et les variations : $x \\mapsto x^2$, $x \\mapsto \\frac{1}{x}$, $x \\mapsto \\sqrt{x}$, $x \\mapsto x^3$, $x \\mapsto |x|$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":457,"term":"histogramme","sense":null,"grade":"2","tags":["statistiques"],"definitions":{"items":[{"grade":"2","content":"Diagramme qui représente des données regroupées en classes : pour chaque classe, un rectangle dont l'aire est proportionnelle à l'effectif."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":458,"term":"écart interquartile","sense":null,"grade":"2","tags":["statistiques"],"definitions":{"items":[{"grade":"2","content":"Différence $Q_3 - Q_1$ entre le troisième et le premier quartile : plus il est petit, plus les valeurs centrales de la série sont regroupées."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":459,"term":"forme factorisée","sense":null,"grade":"2","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"2","content":"Écriture d'une expression sous forme d'un produit : $(x - 1)(x + 3)$ est une forme factorisée de $x^2 + 2x - 3$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":460,"term":"probabilité conditionnelle","sense":null,"grade":"2","tags":["probabilités"],"definitions":{"items":[{"grade":"2","content":"Probabilité que l'évènement $B$ se réalise quand on sait que $A$ est réalisé ; on la note $P_A(B)$ et $P_A(B) = \\frac{P(A \\cap B)}{P(A)}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":461,"term":"croissance linéaire","sense":null,"grade":"1_GEN","tags":["suites","fonctions"],"definitions":{"items":[{"grade":"1_GEN","content":"Une grandeur a une croissance linéaire quand elle augmente de la même quantité à chaque étape : $100$, $110$, $120$, $130$… (on ajoute $10$).","sharedWith":["1_SPE"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_SPE"]},{"position":462,"term":"croissance exponentielle","sense":null,"grade":"1_GEN","tags":["suites","fonctions"],"definitions":{"items":[{"grade":"1_GEN","content":"Une grandeur a une croissance exponentielle quand elle est multipliée par le même nombre, plus grand que $1$, à chaque étape : $100$, $110$, $121$, $133{,}1$… (on multiplie par $1{,}1$).","sharedWith":["1_SPE"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_SPE"]},{"position":463,"term":"discret","sense":null,"grade":"1_GEN","tags":["suites"],"definitions":{"items":[{"grade":"1_GEN","content":"Se dit d'une grandeur qui évolue par étapes (chaque année, chaque mois…), par opposition à « continu » : une suite modélise une évolution discrète.","sharedWith":["1_SPE","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_SPE","1_TECHNO"]},{"position":464,"term":"discriminant","sense":null,"grade":"1_SPE","tags":["fonctions","équations"],"definitions":{"items":[{"grade":"1_SPE","content":"Pour $ax^2 + bx + c$ ($a \\neq 0$), le nombre $\\Delta = b^2 - 4ac$ : son signe dit si l'équation $ax^2 + bx + c = 0$ a deux, une ou aucune solution réelle."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":465,"term":"forme canonique","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Écriture d'une fonction polynôme du second degré sous la forme $a(x - \\alpha)^2 + \\beta$ : le sommet de sa parabole est le point $(\\alpha ; \\beta)$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":466,"term":"évènements indépendants","sense":null,"grade":"1_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"1_SPE","content":"Deux évènements $A$ et $B$ sont indépendants si $P(A \\cap B) = P(A) \\times P(B)$ : savoir que l'un est réalisé ne change pas la probabilité de l'autre.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":["événements indépendants"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":467,"term":"épreuve de Bernoulli","sense":null,"grade":"1_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"1_SPE","content":"Expérience aléatoire à deux issues : le succès, de probabilité $p$, et l'échec, de probabilité $1 - p$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":468,"term":"schéma de Bernoulli","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Répétition de $n$ épreuves de Bernoulli identiques et indépendantes."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":469,"term":"loi binomiale","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Loi du nombre de succès dans un schéma de Bernoulli de $n$ épreuves de probabilité de succès $p$ : $P(X = k) = \\binom{n}{k} p^k (1 - p)^{n - k}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":470,"term":"coefficient binomial","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"$\\binom{n}{k}$ (« $k$ parmi $n$ ») : le nombre de façons de choisir $k$ éléments parmi $n$, sans tenir compte de l'ordre. Ex : $\\binom{4}{2} = 6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":471,"term":"factorielle","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"$n! = 1 \\times 2 \\times \\cdots \\times n$ pour $n \\geq 1$, et $0! = 1$ : c'est le nombre de façons de ranger $n$ objets. Ex : $4! = 24$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":472,"term":"raisonnement par récurrence","sense":null,"grade":"T_SPE","tags":["logique","suites"],"definitions":{"items":[{"grade":"T_SPE","content":"Pour démontrer qu'une propriété $P(n)$ est vraie pour tout entier $n \\geq n_0$ : on vérifie $P(n_0)$ (initialisation), puis on montre que si $P(n)$ est vraie, alors $P(n + 1)$ l'est aussi (hérédité)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":473,"term":"asymptote","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Droite dont la courbe se rapproche autant qu'on veut : si $\\lim_{x \\to +\\infty} f(x) = 2$, la droite d'équation $y = 2$ est asymptote horizontale ; si $\\lim_{x \\to 1} f(x) = +\\infty$, la droite d'équation $x = 1$ est asymptote verticale."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":474,"term":"fonction composée","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"La composée de $u$ suivie de $v$ est la fonction $x \\mapsto v(u(x))$ : on applique $u$, puis $v$ au résultat. Ex : $x \\mapsto \\sqrt{x^2 + 1}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":475,"term":"dérivée seconde","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Dérivée de la dérivée : $f'' = (f')'$. Son signe indique où $f$ est convexe ($f'' \\geq 0$) ou concave ($f'' \\leq 0$)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":476,"term":"point d'inflexion","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Point où la courbe traverse sa tangente : la fonction y passe de convexe à concave, ou l'inverse ; $f''$ y change de signe."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":477,"term":"théorème des valeurs intermédiaires","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Si $f$ est continue sur $[a ; b]$, alors pour tout réel $k$ compris entre $f(a)$ et $f(b)$, l'équation $f(x) = k$ a au moins une solution dans $[a ; b]$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":478,"term":"équation différentielle","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Équation dont l'inconnue est une fonction, reliée à sa dérivée : $y' = 2y$ a pour solutions les fonctions $x \\mapsto Ce^{2x}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":479,"term":"exprimer","sense":null,"grade":"CE1","tags":["calcul-littéral","grandeurs"],"definitions":{"items":[{"grade":"CE1","content":"Exprimer une mesure dans une unité, c'est l'écrire avec cette unité : $1$ m s'exprime aussi $100$ cm."},{"grade":"5","content":"Exprimer une grandeur en fonction d'une autre, c'est l'écrire avec une expression littérale : le périmètre d'un rectangle de largeur $L$ et de longueur $2L$ s'exprime par $6L$. À la différence de « calculer », le résultat contient une lettre."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["exprime","exprimez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":480,"term":"déterminer","sense":null,"grade":"CP","tags":["transversal"],"definitions":{"items":[{"grade":"CP","content":"Trouver ce qui est demandé : déterminer la moitié de $14$, c'est trouver $7$."},{"grade":"5","content":"Trouver ce qui est demandé (un nombre, une expression, un point…) en montrant comment on l'a obtenu : déterminer l'image de $3$ par une fonction, déterminer les solutions d'une équation."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["détermine","déterminez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":481,"term":"justifier","sense":null,"grade":"5","tags":["logique"],"definitions":{"items":[{"grade":"5","content":"Donner les raisons qui montrent qu'une réponse est vraie : un calcul, une propriété, une mesure ou un contre-exemple."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["justifie","justifiez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":482,"term":"vérifier","sense":null,"grade":"CP","tags":["transversal"],"definitions":{"items":[{"grade":"CP","content":"S'assurer qu'une réponse est juste : vérifier avec la règle que des points sont alignés, ou refaire un calcul autrement."},{"grade":"5","content":"Vérifier qu'un nombre est solution d'une équation, c'est le remplacer dans l'équation et constater que l'égalité est vraie."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["vérifie","vérifiez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":483,"term":"tracer","sense":null,"grade":"CE2","tags":["géométrie"],"definitions":{"items":[{"grade":"CE2","content":"Dessiner une ligne ou une figure avec la règle, l'équerre ou le compas : tracer un segment de $5$ cm."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["trace","tracez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":484,"term":"estimer","sense":null,"grade":"CE1","tags":["transversal","grandeurs"],"definitions":{"items":[{"grade":"CE1","content":"Donner une valeur approchée sans calcul exact ni mesure précise : estimer la longueur de la classe, ou que $298 + 403$ fait environ $700$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["estime","estimez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":485,"term":"comparer","sense":null,"grade":"CP","tags":["entiers","transversal"],"definitions":{"items":[{"grade":"CP","content":"Dire lequel de deux nombres, de deux longueurs ou de deux collections est le plus grand, ou s'ils sont égaux ; on écrit $<$, $>$ ou $=$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["compare","comparez"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":486,"term":"encadrer","sense":null,"grade":"CP","tags":["entiers","décimaux"],"definitions":null,"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["encadre","encadrez"],"auto_link":true,"derived_from":"encadrement","see_also":null,"shared_with":[]},{"position":487,"term":"complément","sense":null,"grade":"CP","tags":["entiers","operations"],"definitions":{"items":[{"grade":"CP","content":"Ce qu'il faut ajouter à un nombre pour atteindre un autre nombre. Ex : le complément de $7$ à $10$ est $3$, car $7 + 3 = 10$ ; le complément de $74$ à la dizaine supérieure est $6$, car $74 + 6 = 80$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":488,"term":"étalon","sense":null,"grade":"CP","tags":["grandeurs"],"definitions":{"items":[{"grade":"CP","content":"Objet que l'on choisit pour mesurer, en le reportant bout à bout autant de fois qu'il faut. Ex : la table mesure $8$ crayons : le crayon sert d'étalon."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":489,"term":"balance","sense":null,"grade":"CP","tags":["grandeurs"],"definitions":{"items":[{"grade":"CP","content":"Instrument qui sert à comparer des objets pour savoir lequel est le plus lourd : sur une balance à deux plateaux, c'est le plateau de l'objet le plus lourd qui descend."},{"grade":"CE1","content":"Une balance sert aussi à peser : certaines balances affichent directement la masse d'un objet, en grammes ou en kilogrammes."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":490,"term":"euro","sense":null,"grade":"CP","tags":["grandeurs"],"definitions":{"items":[{"grade":"CP","content":"Monnaie utilisée en France et dans de nombreux pays d'Europe, notée € ; on paie avec des pièces et des billets. Ex : dix pièces de $1$ € ont la même valeur qu'un billet de $10$ €."},{"grade":"CE1","content":"Un euro vaut $100$ centimes. Ex : $2$ € et $5$ centimes s'écrit $2{,}05$ €, alors que $2$ € et $50$ centimes s'écrit $2{,}50$ €."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":491,"term":"tableau à double entrée","sense":null,"grade":"CP","tags":["statistiques"],"definitions":{"items":[{"grade":"CP","content":"Tableau avec des lignes et des colonnes : chaque case se trouve au croisement d'une ligne et d'une colonne. Ex : pour savoir combien de garçons viennent à vélo, on lit la case où la ligne « vélo » croise la colonne « garçons »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":492,"term":"table d'addition","sense":null,"grade":"CP","tags":["entiers","operations"],"definitions":{"items":[{"grade":"CP","content":"Ensemble des résultats des additions de deux nombres de $0$ à $10$, que l'on apprend par cœur : $6 + 7 = 13$, $8 + 5 = 13$… La savoir dans les deux sens, c'est aussi savoir compléter $6 + \\ldots = 13$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":493,"term":"quart de tour","sense":null,"grade":"CP","tags":["géométrie"],"definitions":{"items":[{"grade":"CP","content":"Mouvement où l'on tourne sur place pour se retrouver tourné vers sa droite ou vers sa gauche. Ex : un robot qui pivote d'un quart de tour à droite regarde ensuite vers sa droite ; avec $4$ quarts de tour dans le même sens, il fait un tour complet."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":494,"term":"opération inverse","sense":null,"grade":"CP","tags":["operations"],"definitions":{"items":[{"grade":"CP","content":"Opération qui défait ce qu'une autre opération a fait : la soustraction est l'opération inverse de l'addition. Ex : $32 + 15 = 47$, donc $47 - 15 = 32$."},{"grade":"CE2","content":"La division est l'opération inverse de la multiplication : $4 \\times 5 = 20$, donc $20 \\div 5 = 4$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":495,"term":"poser une opération","sense":null,"grade":"CP","tags":["operations"],"definitions":{"items":[{"grade":"CP","content":"Écrire les nombres les uns sous les autres, les unités sous les unités et les dizaines sous les dizaines, puis calculer colonne par colonne en commençant par les unités. Ex : pour poser $45 + 37$, on écrit $37$ sous $45$, le $7$ sous le $5$ et le $3$ sous le $4$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":496,"term":"données","sense":null,"grade":"CP","tags":["statistiques"],"definitions":{"items":[{"grade":"CP","content":"Informations dont on se sert pour répondre à une question : les nombres donnés dans l'énoncé d'un problème, ou les réponses recueillies lors d'une enquête, que l'on range dans un tableau ou un diagramme. Ex : le fruit préféré de chaque élève de la classe."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":497,"term":"dénombrer","sense":null,"grade":"CP","tags":["entiers","numération"],"definitions":{"items":[{"grade":"CP","content":"Trouver combien il y a d'objets dans une collection, en les comptant ou en les groupant par dix. Ex : $3$ paquets de dix crayons et $4$ crayons seuls, cela fait $34$ crayons."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":498,"term":"demi-heure","sense":null,"grade":"CE1","tags":["grandeurs"],"definitions":{"items":[{"grade":"CE1","content":"Moitié d'une heure : une demi-heure dure $30$ minutes, et deux demi-heures font une heure. Pendant une demi-heure, la grande aiguille de l'horloge fait un demi-tour."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":499,"term":"instant","sense":null,"grade":"CE1","tags":["grandeurs"],"definitions":{"items":[{"grade":"CE1","content":"Moment précis, que l'on peut lire sur une horloge : la classe commence à l'instant $8\\,\\text{h}\\,30$. Le temps qui passe entre deux instants s'appelle une durée."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":500,"term":"parité","sense":null,"grade":"CE1","tags":["entiers","arithmétique"],"definitions":{"items":[{"grade":"CE1","content":"La parité d'un nombre entier, c'est le fait qu'il soit pair ou impair. Ex : $37$ est impair, car son chiffre des unités est $7$ ; $50$ est pair."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":501,"term":"arbre de dénombrement","sense":null,"grade":"CE2","tags":["operations","probabilités"],"definitions":{"items":[{"grade":"CE2","content":"Dessin en forme d'arbre qui montre toutes les façons de combiner des choix, avec une branche pour chaque choix. Ex : avec $2$ chapeaux, $3$ tee-shirts et $2$ pantalons, l'arbre montre $12$ costumes différents, car $2 \\times 3 \\times 2 = 12$."},{"grade":"CM2","content":"Il sert aussi à trouver toutes les issues d'une expérience aléatoire en deux étapes : en lançant deux fois une pièce, l'arbre montre $4$ issues (pile-pile, pile-face, face-pile, face-face)."}]},"exemples":null,"history":null,"image":null,"synonyms":["arbre des possibles"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":502,"term":"écart","sense":null,"grade":"CE1","tags":["operations"],"definitions":{"items":[{"grade":"CE1","content":"De combien un nombre est plus grand qu'un autre. Ex : Lucie a $12$ billes et Léo en a $8$ : l'écart est de $4$ billes, car $8 + 4 = 12$ ; Lucie a $4$ billes de plus que Léo."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":503,"term":"fois plus","sense":null,"grade":"CE1","tags":["operations"],"definitions":{"items":[{"grade":"CE1","content":"« Trois fois plus » veut dire qu'on multiplie par $3$. Ex : Léo a $4$ billes et Lucie trois fois plus : $4 \\times 3 = 12$ billes. À ne pas confondre avec « $3$ de plus » : $4 + 3 = 7$."},{"grade":"CE2","content":"« Trois fois moins » veut dire qu'on divise par $3$ : si Lucie a $12$ billes et Léo trois fois moins, Léo en a $12 \\div 3 = 4$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":504,"term":"caractère","sense":"statistique","grade":"CE1","tags":["statistiques"],"definitions":{"items":[{"grade":"CE1","content":"Ce que l'on observe chez chaque personne ou chaque objet lors d'une enquête. Ex : dans l'enquête « Quel est ton fruit préféré ? », le caractère étudié est le fruit préféré."},{"grade":"CE2","content":"Un caractère peut être qualitatif, comme une couleur ou un moyen de transport, ou quantitatif, c'est-à-dire un nombre, comme l'âge ou le nombre de frères et sœurs."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":505,"term":"cardinal","sense":null,"grade":"CP","tags":["entiers","numération"],"definitions":{"items":[{"grade":"CP","content":"Nombre d'objets d'une collection. Ex : la collection des doigts d'une main a pour cardinal $5$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":506,"term":"centimètre carré","sense":null,"grade":"CM1","tags":["grandeurs","géométrie"],"definitions":{"items":[{"grade":"CM1","content":"Unité d'aire, notée $\\text{cm}^2$ : c'est l'aire d'un carré de $1$ cm de côté. Ex : une figure que l'on peut recouvrir exactement avec $6$ de ces carrés a une aire de $6\\,\\text{cm}^2$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":507,"term":"mètre carré","sense":null,"grade":"CM2","tags":["grandeurs","géométrie"],"definitions":{"items":[{"grade":"CM2","content":"Unité d'aire, notée $\\text{m}^2$ : c'est l'aire d'un carré de $1$ m de côté. Ex : le sol d'une salle de classe mesure environ $60\\,\\text{m}^2$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":508,"term":"échelle de probabilités","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Ligne sur laquelle on range des évènements selon leurs chances de se produire, dans l'ordre : impossible, peu probable, une chance sur deux, probable, certain. Ex : « obtenir $7$ avec un dé à six faces » se place tout au bout, sur « impossible »."},{"grade":"6","content":"L'échelle est graduée de $0$ (impossible) à $1$ (certain) : on place chaque évènement à sa probabilité, par exemple « obtenir pile » à $\\frac{1}{2}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":509,"term":"égalité à trous","sense":null,"grade":"CP","tags":["operations","équations"],"definitions":{"items":[{"grade":"CP","content":"Égalité dans laquelle il manque un nombre, qu'il faut trouver. Ex : dans $4 + \\ldots = 12$, le nombre qui manque est $8$."},{"grade":"6","content":"Le nombre qui manque n'est pas toujours entier : dans $7 \\times \\ldots = 3$, c'est la fraction $\\frac{3}{7}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":510,"term":"hasard","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Ce qui décide d'un résultat que personne ne peut prévoir à l'avance : quand on lance un dé, c'est le hasard qui donne le nombre obtenu. Tirer une carte « au hasard », c'est la prendre sans pouvoir la choisir."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":511,"term":"tonne","sense":null,"grade":"CE2","tags":["grandeurs"],"definitions":{"items":[{"grade":"CE2","content":"Unité de masse, notée $\\text{t}$, pour les objets très lourds : $1\\,\\text{t} = 1\\,000\\,\\text{kg}$. Ex : une petite voiture pèse environ $1$ tonne."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":512,"term":"seconde","sense":"durée","grade":"CM2","tags":["grandeurs"],"definitions":{"items":[{"grade":"CM2","content":"Unité de durée très courte, notée $\\text{s}$ : il y a $60$ secondes dans une minute. Ex : les meilleurs coureurs font le $100$ mètres en moins de $10$ secondes."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":false,"derived_from":null,"see_also":null,"shared_with":[]},{"position":513,"term":"instruction","sense":null,"grade":"CP","tags":["transversal"],"definitions":{"items":[{"grade":"CP","content":"Ordre précis qui dit ce qu'il faut faire, à une personne, à un robot ou à un ordinateur. Ex : « avance d'une case » et « pivote d'un quart de tour à droite » sont des instructions pour un robot."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":514,"term":"parenthèses","sense":null,"grade":"CM1","tags":["operations"],"definitions":{"items":[{"grade":"CM1","content":"Signes $($ et $)$ qui entourent une partie d'un calcul : on effectue d'abord le calcul entre parenthèses. Ex : $(12 - 2) \\times 3 = 10 \\times 3 = 30$, mais $12 - (2 \\times 3) = 12 - 6 = 6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":515,"term":"programme de construction","sense":null,"grade":"CM1","tags":["géométrie"],"definitions":{"items":[{"grade":"CM1","content":"Liste d'instructions, à suivre dans l'ordre, pour tracer une figure. Ex : « Trace un carré de $4$ cm de côté. Trace le cercle de centre un sommet du carré et de rayon $4$ cm. »"}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":516,"term":"définition","sense":null,"grade":"CM1","tags":["logique"],"definitions":{"items":[{"grade":"CM1","content":"Phrase qui dit exactement ce qu'est un objet mathématique, pour pouvoir le reconnaître sans se tromper. Ex : la définition du rectangle est « un quadrilatère qui a quatre angles droits »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":517,"term":"diviseur commun","sense":null,"grade":"CM2","tags":["entiers","arithmétique","divisibilité"],"definitions":{"items":[{"grade":"CM2","content":"Nombre qui est à la fois un diviseur de deux nombres : la division de chacun d'eux par ce nombre tombe juste. Ex : les diviseurs communs à $12$ et $18$ sont $1$, $2$, $3$ et $6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":518,"term":"multiple commun","sense":null,"grade":"CM2","tags":["entiers","arithmétique","divisibilité"],"definitions":{"items":[{"grade":"CM2","content":"Nombre qui est à la fois un multiple de deux nombres. Ex : $12$ est un multiple commun à $4$ et $6$, car $4 \\times 3 = 12$ et $6 \\times 2 = 12$ ; $24$ et $36$ aussi."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":519,"term":"expériences indépendantes","sense":null,"grade":"CM2","tags":["probabilités"],"definitions":{"items":[{"grade":"CM2","content":"Deux expériences sont indépendantes quand le résultat de la première ne change pas les chances de la deuxième. Ex : un dé « ne se souvient pas » du lancer précédent : au deuxième lancer, on a toujours $1$ chance sur $6$ d'obtenir $6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":520,"term":"trapèze rectangle","sense":null,"grade":"CM2","tags":["géométrie"],"definitions":{"items":[{"grade":"CM2","content":"Trapèze qui a deux angles droits : un de ses côtés est perpendiculaire aux deux côtés parallèles. Ex : en coupant un carré par un trait qui va du milieu d'un côté à un sommet du côté opposé, on obtient un triangle rectangle et un trapèze rectangle."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":521,"term":"angles opposés par le sommet","sense":null,"grade":"6","tags":["géométrie"],"definitions":{"items":[{"grade":"6","content":"Deux angles sont opposés par le sommet quand ils ont le même sommet et que les côtés de l'un prolongent ceux de l'autre : deux droites qui se coupent forment deux paires d'angles qui se font face. Deux angles opposés par le sommet ont toujours la même mesure."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":522,"term":"siècle","sense":null,"grade":"6","tags":["grandeurs"],"definitions":{"items":[{"grade":"6","content":"Durée de $100$ ans. Un millénaire dure $1\\,000$ ans, c'est-à-dire $10$ siècles. Ex : le XXIe siècle va de l'an $2001$ à l'an $2100$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":523,"term":"année bissextile","sense":null,"grade":"6","tags":["grandeurs"],"definitions":{"items":[{"grade":"6","content":"Année de $366$ jours au lieu de $365$ : le mois de février y compte $29$ jours au lieu de $28$. Elle revient en général tous les $4$ ans. Ex : $2024$ et $2028$ sont des années bissextiles."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":524,"term":"cas favorable","sense":null,"grade":"6","tags":["probabilités"],"definitions":{"items":[{"grade":"6","content":"Issue d'une expérience aléatoire qui réalise l'évènement étudié. Ex : avec un dé, pour « obtenir un nombre pair », les cas favorables sont $2$, $4$ et $6$ ; les issues étant équiprobables, la probabilité est le nombre de cas favorables divisé par le nombre total de cas : $\\frac{3}{6}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":525,"term":"centimètre cube","sense":null,"grade":"6","tags":["grandeurs"],"definitions":{"items":[{"grade":"6","content":"Unité de volume, notée $\\text{cm}^3$ : c'est le volume d'un cube de $1\\,\\text{cm}$ d'arête. Ex : un pavé formé de $2 \\times 3 \\times 4 = 24$ cubes de $1\\,\\text{cm}$ d'arête a un volume de $24\\,\\text{cm}^3$."},{"grade":"5","content":"Lien avec les contenances : $1\\,\\text{cm}^3 = 1\\,\\text{mL}$ et $1\\,\\text{L} = 1\\,\\text{dm}^3 = 1\\,000\\,\\text{cm}^3$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":526,"term":"concourantes","sense":null,"grade":"6","tags":["géométrie"],"definitions":{"items":[{"grade":"6","content":"Trois droites (ou plus) sont concourantes quand elles passent toutes par un même point. Ex : les trois médiatrices d'un triangle sont concourantes ; leur point commun est le centre du cercle circonscrit au triangle."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":527,"term":"enquête","sense":null,"grade":"CP","tags":["statistiques"],"definitions":{"items":[{"grade":"CP","content":"On pose la même question à plusieurs personnes et on note leurs réponses pour pouvoir les compter. Ex : demander à chaque élève de la classe quel est son fruit préféré."},{"grade":"6","content":"Une enquête statistique se fait en plusieurs étapes : choisir la question et les personnes (ou les objets) étudiés, recueillir les données, les ranger dans un tableau ou un diagramme, puis les interpréter."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":528,"term":"nombre non décimal","sense":null,"grade":"6","tags":["décimaux","fractions"],"definitions":{"items":[{"grade":"6","content":"Nombre qui ne peut pas s'écrire comme une fraction décimale : son écriture à virgule ne s'arrête jamais. Ex : $\\frac{1}{3} = 0{,}333\\ldots$, les $3$ continuent sans fin."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":529,"term":"propriété caractéristique","sense":null,"grade":"6","tags":["logique","géométrie"],"definitions":{"items":[{"grade":"6","content":"Propriété qui suffit à reconnaître un objet : tous les objets de cette sorte la vérifient, et ils sont les seuls. Ex : la médiatrice d'un segment est formée de tous les points situés à la même distance des deux extrémités du segment, et seulement de ces points."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":530,"term":"retour à l'unité","sense":null,"grade":"6","tags":["proportionnalité"],"definitions":{"items":[{"grade":"6","content":"Méthode pour résoudre un problème de proportionnalité : on calcule d'abord ce qui correspond à une seule unité, puis on multiplie. Ex : si $4$ stylos coûtent $2$ €, $1$ stylo coûte $0{,}50$ €, donc $7$ stylos coûtent $3{,}50$ €."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":531,"term":"équiprobable","sense":null,"grade":"CM2","tags":["probabilités"],"definitions":{"items":[{"grade":"CM2","content":"Se dit d'issues qui ont toutes la même probabilité (les mêmes chances) de se produire. Ex : avec un dé équilibré, les six faces sont équiprobables."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":532,"term":"angles alternes internes","sense":null,"grade":"5","tags":["géométrie"],"definitions":{"items":[{"grade":"5","content":"Deux droites $(d)$ et $(d')$ coupées par une sécante forment des angles alternes internes : un à chaque point d'intersection, de part et d'autre de la sécante et entre les deux droites. Si $(d)$ et $(d')$ sont parallèles, ces angles ont la même mesure ; réciproquement, s'ils ont la même mesure, les droites sont parallèles."}]},"exemples":null,"history":null,"image":null,"synonyms":["angles alternes-internes"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":533,"term":"angles correspondants","sense":null,"grade":"5","tags":["géométrie"],"definitions":{"items":[{"grade":"5","content":"Deux droites $(d)$ et $(d')$ coupées par une sécante forment des angles correspondants : un à chaque point d'intersection, placés de la même façon, du même côté de la sécante et chacun du même côté de sa droite. Si $(d)$ et $(d')$ sont parallèles, ces angles ont la même mesure ; réciproquement, s'ils ont la même mesure, les droites sont parallèles."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":534,"term":"contre-exemple","sense":null,"grade":"5","tags":["logique"],"definitions":{"items":[{"grade":"5","content":"Exemple qui montre qu'une affirmation générale est fausse ; un seul suffit. Ex : « tous les multiples de $3$ sont impairs » est faux, car $6$ est un multiple de $3$ qui est pair : $6$ est un contre-exemple."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":535,"term":"diagramme circulaire","sense":null,"grade":"CM2","tags":["statistiques"],"definitions":{"items":[{"grade":"CM2","content":"Diagramme en forme de disque partagé en parts : chaque part représente une catégorie, et plus il y a de personnes ou d'objets dans une catégorie, plus sa part est grande. Ex : si la moitié des élèves vient à pied, la part « à pied » occupe la moitié du disque."},{"grade":"5","content":"Chaque secteur a un angle proportionnel à l'effectif qu'il représente : le disque entier, soit $360°$, correspond à l'effectif total. Ex : une catégorie qui regroupe le quart des individus a un secteur de $90°$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":536,"term":"nuage de points","sense":null,"grade":"5","tags":["statistiques","proportionnalité"],"definitions":{"items":[{"grade":"5","content":"Ensemble de points placés dans un repère pour représenter des données : chaque point a pour coordonnées deux valeurs liées, par exemple l'âge et la taille d'un enfant. Si les points sont alignés avec l'origine du repère, les deux grandeurs sont proportionnelles."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":537,"term":"perspective cavalière","sense":null,"grade":"CE1","tags":["géométrie"],"definitions":{"items":[{"grade":"CE1","content":"Façon de dessiner un solide sur une feuille pour qu'on le voie en relief : la face de devant est dessinée telle qu'elle est, les arêtes qui partent vers l'arrière sont tracées en biais, et les arêtes cachées sont en pointillés."},{"grade":"5","content":"Les faces de devant et de derrière sont dessinées en vraie grandeur ; les arêtes fuyantes (perpendiculaires à la face de devant) sont tracées en biais et raccourcies ; deux arêtes parallèles dans la réalité restent parallèles sur le dessin. Ex : un cube y est dessiné avec deux carrés et quatre parallélogrammes."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":538,"term":"priorités opératoires","sense":null,"grade":"5","tags":["operations"],"definitions":{"items":[{"grade":"5","content":"Règles qui fixent l'ordre des calculs : d'abord ce qui est entre parenthèses, puis les puissances, puis les multiplications et divisions, enfin les additions et soustractions ; à priorité égale, on calcule de gauche à droite. Ex : $5 + 2 \\times 3 = 5 + 6 = 11$ (et non $7 \\times 3 = 21$)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":539,"term":"programme","sense":"informatique","grade":"CM2","tags":["transversal"],"definitions":{"items":[{"grade":"CM2","content":"Suite d'instructions écrite pour être exécutée par un robot ou un ordinateur. Ex : « avancer de $2$ cases, pivoter d'un quart de tour à droite, avancer de $3$ cases »."},{"grade":"5","content":"Algorithme écrit dans un langage de programmation (par blocs comme Scratch, ou Python) : il reçoit des données en entrée (par exemple un nombre saisi), les traite par des instructions, et produit des résultats en sortie (un nombre affiché, un dessin)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":540,"term":"propriété de linéarité","sense":null,"grade":"CM1","tags":["proportionnalité"],"definitions":{"items":[{"grade":"CM1","content":"Propriété des situations de proportionnalité : si on multiplie une quantité par un nombre, la quantité qui lui correspond est multipliée par le même nombre. Ex : si $4$ pains coûtent $7$ €, $12$ pains, c'est-à-dire $3$ fois plus, coûtent $3$ fois plus : $21$ €."},{"grade":"CM2","content":"Dans une situation de proportionnalité, on peut aussi additionner : à la somme de deux quantités correspond la somme des quantités qui leur correspondent. Ex : si $3$ cahiers coûtent $6$ € et $2$ cahiers coûtent $4$ €, alors $5$ cahiers coûtent $6 + 4 = 10$ €."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":541,"term":"strictement positif","sense":null,"grade":"5","tags":["relatifs"],"definitions":{"items":[{"grade":"5","content":"Un nombre est strictement positif quand il est supérieur à $0$ sans être égal à $0$. Ex : $3$ et $0{,}5$ sont strictement positifs ; $0$ est positif, mais pas strictement positif. De même, un nombre strictement négatif est inférieur à $0$ sans être égal à $0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":542,"term":"successeur","sense":null,"grade":"5","tags":["entiers","calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Le successeur d'un nombre entier est l'entier qui vient juste après lui : on lui ajoute $1$. Ex : le successeur de $7$ est $8$ ; celui de $n$ est $n + 1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":543,"term":"prédécesseur","sense":null,"grade":"5","tags":["entiers","calcul-littéral"],"definitions":{"items":[{"grade":"5","content":"Le prédécesseur d'un nombre entier est l'entier qui vient juste avant lui : on lui retire $1$. Ex : le prédécesseur de $8$ est $7$ ; celui de $n$ est $n - 1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":544,"term":"tableur","sense":null,"grade":"CM1","tags":["transversal"],"definitions":{"items":[{"grade":"CM1","content":"Logiciel qui affiche une grille de cases, appelées cellules, rangées en lignes et en colonnes. On y écrit des nombres ou des formules de calcul, et le logiciel fait les calculs tout seul. Ex : prolonger très loin une suite de nombres."},{"grade":"5","content":"Chaque cellule est repérée par la lettre de sa colonne et le numéro de sa ligne, par exemple B3. Une formule commence par « = » et peut utiliser d'autres cellules : « =2*A1+3 » ; recopiée vers le bas, elle refait le calcul ligne par ligne."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":545,"term":"demi-cercle","sense":null,"grade":"4","tags":["géométrie"],"definitions":{"items":[{"grade":"4","content":"Moitié d'un cercle, limitée par les deux extrémités d'un de ses diamètres. Ex : si $[AB]$ est un diamètre d'un cercle et $M$ un autre point de ce cercle, le triangle $ABM$ est rectangle en $M$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":546,"term":"droite des milieux","sense":null,"grade":"4","tags":["géométrie"],"definitions":{"items":[{"grade":"4","content":"Dans un triangle, droite qui passe par les milieux de deux côtés : elle est parallèle au troisième côté, et le segment qui joint ces deux milieux mesure la moitié du troisième côté. De plus, la droite qui passe par le milieu d'un côté parallèlement à un deuxième côté coupe le troisième côté en son milieu. Ex : dans un triangle $ABC$, si $I$ et $J$ sont les milieux de $[AB]$ et $[AC]$, alors $(IJ)$ est parallèle à $(BC)$ et $IJ = \\frac{BC}{2}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":547,"term":"épreuve","sense":null,"grade":"4","tags":["probabilités"],"definitions":{"items":[{"grade":"4","content":"Chacune des étapes d'une expérience aléatoire qui se déroule en plusieurs temps. Ex : lancer une pièce, puis lancer un dé, c'est une expérience à deux épreuves."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":548,"term":"fluctuation","sense":null,"grade":"4","tags":["probabilités","statistiques"],"definitions":{"items":[{"grade":"4","content":"Variation des fréquences observées d'une série d'essais à l'autre, même quand chaque série compte le même nombre d'essais. Ex : sur $50$ lancers d'une pièce, on obtient $23$ « pile », puis $28$ sur $50$ autres lancers : les fréquences $0{,}46$ et $0{,}56$ varient autour de la probabilité $0{,}5$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":549,"term":"grandeur quotient","sense":null,"grade":"4","tags":["grandeurs","proportionnalité"],"definitions":{"items":[{"grade":"4","content":"Grandeur obtenue en divisant une grandeur par une autre ; son unité combine les deux unités. Ex : une vitesse est une distance divisée par une durée, en $\\text{km/h}$ ; un débit est un volume divisé par une durée, en $\\text{L/min}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":550,"term":"partage proportionnel","sense":null,"grade":"4","tags":["proportionnalité"],"definitions":{"items":[{"grade":"4","content":"Partage d'une quantité en parts proportionnelles à des nombres donnés. Ex : partager $600$ € proportionnellement à $2$ et $3$ : on fait $2 + 3 = 5$ parts égales de $120$ €, d'où $2 \\times 120 = 240$ € et $3 \\times 120 = 360$ €."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":551,"term":"quatrième proportionnelle","sense":null,"grade":"4","tags":["proportionnalité"],"definitions":{"items":[{"grade":"4","content":"Nombre qui manque dans un tableau de proportionnalité de quatre cases quand on connaît les trois autres. Ex : si $3$ kg de pommes coûtent $12$ €, $5$ kg coûtent $\\frac{12 \\times 5}{3} = 20$ € : $20$ est la quatrième proportionnelle."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":552,"term":"raisonnement par l'absurde","sense":null,"grade":"4","tags":["logique"],"definitions":{"items":[{"grade":"4","content":"Raisonnement qui suppose le contraire de ce qu'on veut démontrer et montre que cela mène à une contradiction : la supposition est donc fausse. Ex : pour démontrer qu'il n'existe pas de plus grand nombre entier, on suppose qu'il en existe un, $N$ ; mais $N + 1$ est un entier plus grand, c'est absurde."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":553,"term":"simulation","sense":null,"grade":"6","tags":["probabilités"],"definitions":{"items":[{"grade":"6","content":"Imitation d'une expérience aléatoire, souvent avec un logiciel, pour la répéter un grand nombre de fois et observer les fréquences des résultats. Ex : faire tourner $1\\,000$ fois une roue de loterie virtuelle."},{"grade":"3","content":"Pour simuler une expérience, on la remplace par un tirage au hasard qui a les mêmes probabilités, souvent fait par un programme. Ex : tirer au hasard un nombre entier entre $1$ et $6$ simule le lancer d'un dé équilibré."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":554,"term":"boîte à moustaches","sense":null,"grade":"3","tags":["statistiques"],"definitions":{"items":[{"grade":"3","content":"Diagramme qui résume une série statistique sur un axe gradué : une « boîte » va du premier quartile $Q_1$ au troisième quartile $Q_3$, coupée par un trait à la médiane, et deux « moustaches » la prolongent jusqu'au minimum et jusqu'au maximum. On dit aussi « diagramme en boîte »."}]},"exemples":null,"history":null,"image":null,"synonyms":["diagramme en boîte"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":555,"term":"double distributivité","sense":null,"grade":"3","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"3","content":"Règle pour développer le produit de deux sommes : on multiplie chaque terme de la première par chaque terme de la seconde, puis on ajoute les produits : $(a + b)(c + d) = ac + ad + bc + bd$. Ex : $(x + 2)(x + 3) = x^2 + 3x + 2x + 6 = x^2 + 5x + 6$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":556,"term":"effectif cumulé","sense":null,"grade":"3","tags":["statistiques"],"definitions":{"items":[{"grade":"3","content":"L'effectif cumulé croissant d'une valeur est le nombre d'individus dont la valeur est inférieure ou égale à celle-ci : on additionne les effectifs depuis la plus petite valeur. Ex : notes $8$ ($3$ élèves), $10$ ($5$ élèves), $12$ ($4$ élèves) ; l'effectif cumulé croissant de $10$ est $3 + 5 = 8$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":557,"term":"équation produit nul","sense":null,"grade":"3","tags":["équations"],"definitions":{"items":[{"grade":"3","content":"Équation de la forme $A \\times B = 0$, où $A$ et $B$ sont des expressions. Un produit est nul si et seulement si l'un au moins de ses facteurs est nul : on résout donc $A = 0$ ou $B = 0$. Ex : $(x - 2)(x + 5) = 0$ a pour solutions $2$ et $-5$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":558,"term":"facteur commun","sense":null,"grade":"3","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"3","content":"Facteur qu'on retrouve dans chaque terme d'une somme, ou à la fois au numérateur et au dénominateur d'un quotient. Ex : dans $5x + 15 = 5 \\times x + 5 \\times 3$, le facteur commun est $5$, d'où $5x + 15 = 5(x + 3)$ ; il peut être une expression : $(x + 1) \\times 2 + (x + 1) \\times x = (x + 1)(2 + x)$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":559,"term":"relation de Chasles","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Pour trois points $A$, $B$ et $C$ quelconques : $\\overrightarrow{AB} + \\overrightarrow{BC} = \\overrightarrow{AC}$. Enchaîner la translation qui transforme $A$ en $B$ puis celle qui transforme $B$ en $C$ revient à faire la translation qui transforme $A$ en $C$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":560,"term":"section","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Figure plane obtenue en coupant un solide par un plan. Ex : la section d'un pavé droit par un plan parallèle à une face est un rectangle de mêmes dimensions que cette face ; la section d'une boule par un plan qui la coupe est un disque."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":561,"term":"somme de deux vecteurs","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"La somme $\\vec{u} + \\vec{v}$ est le vecteur de la translation obtenue en enchaînant la translation de vecteur $\\vec{u}$ puis celle de vecteur $\\vec{v}$. Ex : $\\overrightarrow{AB} + \\overrightarrow{BC} = \\overrightarrow{AC}$ ; et si $ABCD$ est un parallélogramme, $\\overrightarrow{AB} + \\overrightarrow{AD} = \\overrightarrow{AC}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":562,"term":"vecteur nul","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Vecteur de la translation qui ne déplace aucun point, noté $\\vec{0}$ : $\\overrightarrow{AA} = \\overrightarrow{BB} = \\vec{0}$. C'est le seul vecteur de longueur nulle ; il n'a ni direction ni sens."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":563,"term":"vecteurs égaux","sense":null,"grade":"3","tags":["géométrie"],"definitions":{"items":[{"grade":"3","content":"Deux vecteurs sont égaux quand ils définissent la même translation : même direction, même sens et même longueur. Ex : $\\overrightarrow{AB} = \\overrightarrow{DC}$ exactement quand $ABCD$ est un parallélogramme (éventuellement aplati)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":564,"term":"affectation","sense":null,"grade":"2","tags":["transversal"],"definitions":{"items":[{"grade":"2","content":"Instruction qui donne une valeur à une variable, en remplaçant celle qu'elle contenait. En langage naturel, on écrit $a \\leftarrow 5$ (en Python : « a = 5 », où le signe = n'est pas une égalité) ; ainsi $a \\leftarrow a + 1$ augmente de $1$ la valeur de $a$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":565,"term":"amplitude","sense":null,"grade":"2","tags":["décimaux","statistiques"],"definitions":{"items":[{"grade":"2","content":"L'amplitude d'un intervalle de bornes $a$ et $b$ (avec $a < b$) est la différence $b - a$. Ex : l'encadrement $1{,}41 \\leq \\sqrt{2} \\leq 1{,}42$ a pour amplitude $0{,}01$ ; en statistique, la classe $[150 ; 160[$ a pour amplitude $10$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":566,"term":"chiffres significatifs","sense":null,"grade":"2","tags":["décimaux","numération"],"definitions":{"items":[{"grade":"2","content":"Chiffres de l'écriture décimale d'un nombre, comptés à partir du premier chiffre non nul (en lisant de gauche à droite) jusqu'au dernier chiffre écrit ; plus il y en a, plus la valeur donnée est précise. Ex : $0{,}0305$ a trois chiffres significatifs ($3$, $0$ et $5$) ; $3{,}1416$ arrondi à deux chiffres significatifs donne $3{,}1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":567,"term":"classe","sense":"statistique","grade":"2","tags":["statistiques"],"definitions":{"items":[{"grade":"2","content":"Intervalle de valeurs dans lequel on regroupe les données d'une série statistique ; l'effectif de la classe est le nombre de données qui y tombent. Ex : pour des tailles en $\\text{cm}$, la classe $[150 ; 160[$ contient les tailles $t$ telles que $150 \\leq t < 160$, et son centre est $155$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":false,"derived_from":null,"see_also":null,"shared_with":[]},{"position":568,"term":"négation","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"La négation d'une proposition $P$ est la proposition « non $P$ » : elle est vraie quand $P$ est fausse, et fausse quand $P$ est vraie. Ex : pour un réel $x$ donné, la négation de « $x > 3$ » est « $x \\leq 3$ » ; celle de « $P$ et $Q$ » est « non $P$ ou non $Q$ »."},{"grade":"1_SPE","content":"Pour nier une proposition quantifiée, on échange « pour tout » et « il existe » et on nie la propriété. Ex : la négation de « pour tout réel $x$, $x^2 > 0$ » est « il existe un réel $x$ tel que $x^2 \\leq 0$ », qui est vraie ($x = 0$)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":569,"term":"couple","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Deux objets pris dans un ordre précis, notés $(a ; b)$ : $a$ est le premier élément du couple, $b$ le second. Deux couples sont égaux s'ils ont le même premier élément et le même second élément ; ainsi $(1 ; 2) \\neq (2 ; 1)$. Ex : les coordonnées d'un point forment un couple."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":570,"term":"élément","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Chacun des objets qui composent un ensemble. On écrit $x \\in E$ (« $x$ appartient à $E$ ») si $x$ est un élément de $E$, et $x \\notin E$ sinon. Ex : $3 \\in \\{1, 2, 3\\}$, mais $5 \\notin \\{1, 2, 3\\}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":571,"term":"taux d'évolution réciproque","sense":null,"grade":"2","tags":["proportionnalité"],"definitions":{"items":[{"grade":"2","content":"Taux $t'$ de l'évolution qui ramène à la valeur de départ : si un taux $t$ fait passer de $V_1$ à $V_2$, le taux réciproque fait passer de $V_2$ à $V_1$, et $1 + t' = \\frac{1}{1 + t}$. Ex : après une hausse de $25\\,\\%$ ($\\times 1{,}25$), il faut une baisse de $20\\,\\%$ ($\\times 0{,}8$) pour revenir à la valeur de départ."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":572,"term":"fonction cube","sense":null,"grade":"2","tags":["fonctions","puissances"],"definitions":{"items":[{"grade":"2","content":"Fonction définie sur $\\mathbb{R}$ par $f(x) = x^3$. Elle est croissante sur $\\mathbb{R}$, $x^3$ a toujours le même signe que $x$, et sa courbe est symétrique par rapport à l'origine du repère. Ex : $f(2) = 8$ et $f(-2) = -8$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":573,"term":"fonction valeur absolue","sense":null,"grade":"2","tags":["fonctions","relatifs"],"definitions":{"items":[{"grade":"2","content":"Fonction définie sur $\\mathbb{R}$ par $f(x) = |x|$, c'est-à-dire $f(x) = x$ si $x \\geq 0$ et $f(x) = -x$ si $x < 0$. Elle est décroissante sur $]-\\infty ; 0]$ et croissante sur $[0 ; +\\infty[$ ; sa courbe a la forme d'un V, formé de deux demi-droites issues de l'origine."},{"grade":"1_SPE","content":"Elle n'est pas dérivable en $0$ : le taux de variation $\\frac{|h| - |0|}{h}$ vaut $1$ si $h > 0$ et $-1$ si $h < 0$, il n'a donc pas de limite quand $h$ tend vers $0$ (la courbe forme un « coin » à l'origine)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":574,"term":"fréquence conditionnelle","sense":null,"grade":"2","tags":["statistiques"],"definitions":{"items":[{"grade":"2","content":"Fréquence calculée à l'intérieur d'une sous-population : la fréquence de $B$ parmi les individus de $A$ est l'effectif des individus qui sont à la fois dans $A$ et dans $B$, divisé par l'effectif de $A$. Ex : si $10$ des $40$ internes d'un lycée font du latin, la fréquence des latinistes parmi les internes est $\\frac{10}{40} = 0{,}25$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":575,"term":"indicateur statistique","sense":null,"grade":"4","tags":["statistiques"],"definitions":{"items":[{"grade":"4","content":"Nombre qui résume une série statistique par une seule valeur. Ex : la moyenne, la médiane et l'étendue sont des indicateurs."},{"grade":"2","content":"On distingue les indicateurs de position (moyenne, médiane, quartiles), qui indiquent autour de quelles valeurs se situe la série, et les indicateurs de dispersion (étendue, écart interquartile, écart type), qui mesurent à quel point les valeurs sont étalées."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":576,"term":"loi des grands nombres","sense":null,"grade":"2","tags":["probabilités","statistiques"],"definitions":{"items":[{"grade":"2","content":"Quand on répète un grand nombre de fois la même expérience aléatoire, de façon indépendante, la fréquence observée d'un évènement est, sauf exception, proche de sa probabilité. Ex : sur $10\\,000$ lancers d'une pièce équilibrée, la fréquence de « pile » est presque toujours proche de $0{,}5$."},{"grade":"T_SPE","content":"Si $M_n$ est la moyenne d'un échantillon de taille $n$ d'une variable aléatoire d'espérance $\\mu$, alors pour tout réel $\\delta > 0$, la probabilité $P(|M_n - \\mu| \\geq \\delta)$ tend vers $0$ quand $n$ tend vers $+\\infty$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":577,"term":"monotone","sense":null,"grade":"2","tags":["fonctions"],"definitions":{"items":[{"grade":"2","content":"Une fonction est monotone sur un intervalle $I$ si elle est croissante sur tout $I$, ou décroissante sur tout $I$ ; elle est strictement monotone si elle est strictement croissante ou strictement décroissante sur $I$. Ex : $x \\mapsto x^2$ n'est pas monotone sur $\\mathbb{R}$, mais elle l'est sur $[0 ; +\\infty[$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":578,"term":"proposition","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Énoncé mathématique qui est soit vrai, soit faux. Ex : « $7$ est un nombre premier » est une proposition vraie, « $2 + 2 = 5$ » une proposition fausse ; une proposition peut contenir une variable : « $x > 2$ » est vraie pour $x = 3$ et fausse pour $x = 0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":579,"term":"quantificateur","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Expression qui indique pour quels objets une propriété est affirmée : « pour tout » (ou « quel que soit ») affirme qu'elle est vraie pour tous, « il existe » qu'elle est vraie pour au moins un. Ex : « pour tout réel $x$, $x^2 \\geq 0$ » est vraie ; « il existe un réel $x$ tel que $x^2 = -1$ » est fausse."},{"grade":"1_SPE","content":"On note parfois $\\forall$ (« pour tout ») et $\\exists$ (« il existe »). Un quantificateur est souvent sous-entendu : « si $x > 2$, alors $x^2 > 4$ » veut dire « pour tout réel $x$, si $x > 2$ alors $x^2 > 4$ »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":580,"term":"disjonction des cas","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Raisonnement qui sépare un problème en plusieurs cas couvrant toutes les possibilités, puis traite chaque cas séparément. Ex : pour montrer que $n(n + 1)$ est pair pour tout entier $n$, on étudie le cas « $n$ pair » puis le cas « $n$ impair »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":581,"term":"repère orthonormé","sense":null,"grade":"2","tags":["géométrie","fonctions"],"definitions":{"items":[{"grade":"2","content":"Repère $(O ; I, J)$ du plan dont les axes $(OI)$ et $(OJ)$ sont perpendiculaires et ont la même unité de longueur : $OI = OJ = 1$. On le note aussi $(O ; \\vec{i}, \\vec{j})$, avec $(\\vec{i}, \\vec{j})$ base orthonormée ; c'est dans un tel repère que $AB = \\sqrt{(x_B - x_A)^2 + (y_B - y_A)^2}$."},{"grade":"T_SPE","content":"Dans l'espace, repère $(O ; \\vec{i}, \\vec{j}, \\vec{k})$ dont les trois vecteurs sont orthogonaux deux à deux et de norme $1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":582,"term":"sous-ensemble","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Un ensemble $A$ est un sous-ensemble (ou une partie) d'un ensemble $E$ si tout élément de $A$ est aussi un élément de $E$ ; on écrit $A \\subset E$. Ex : $\\{2, 4\\}$ est un sous-ensemble de $\\{1, 2, 3, 4\\}$, $\\mathbb{N}$ est un sous-ensemble de $\\mathbb{R}$, et $\\varnothing$ comme $E$ lui-même sont des sous-ensembles de $E$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":583,"term":"tableau croisé","sense":null,"grade":"2","tags":["statistiques"],"definitions":{"items":[{"grade":"2","content":"Tableau à double entrée qui répartit une population selon deux caractères : chaque case donne l'effectif des individus qui ont à la fois la modalité de sa ligne et celle de sa colonne, et les totaux figurent en marge. Ex : les élèves d'un lycée répartis selon leur niveau (lignes) et selon qu'ils sont internes ou externes (colonnes)."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":584,"term":"variation absolue","sense":null,"grade":"2","tags":["proportionnalité"],"definitions":{"items":[{"grade":"2","content":"Différence $V_2 - V_1$ entre la valeur d'arrivée $V_2$ et la valeur de départ $V_1$ ; elle s'exprime dans l'unité de la grandeur et elle est négative en cas de baisse. Ex : un prix qui passe de $80$ € à $92$ € a une variation absolue de $+12$ €, alors que sa variation relative (taux d'évolution) est $\\frac{12}{80} = 15\\,\\%$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":585,"term":"équation cartésienne","sense":null,"grade":"2","tags":["géométrie","équations"],"definitions":{"items":[{"grade":"2","content":"Équation de la forme $ax + by + c = 0$, avec $a$ et $b$ non tous les deux nuls, vérifiée exactement par les coordonnées $(x ; y)$ des points d'une droite. Toute droite du plan en a une, et même une infinité, proportionnelles entre elles. Ex : $2x - y + 3 = 0$ est une équation cartésienne de la droite d'équation réduite $y = 2x + 3$."},{"grade":"T_SPE","content":"Dans l'espace muni d'un repère orthonormé, un plan a une équation cartésienne de la forme $ax + by + cz + d = 0$, avec $a$, $b$, $c$ non tous nuls ; le vecteur $\\vec{n}(a ; b ; c)$ est alors normal à ce plan."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":586,"term":"approximation linéaire","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Si $f$ est dérivable en $a$, alors pour $h$ proche de $0$, $f(a + h) \\approx f(a) + f'(a)h$ : près du point d'abscisse $a$, on remplace la courbe par sa tangente. Ex : avec $f(x) = \\sqrt{x}$ et $a = 1$, $\\sqrt{1{,}02} \\approx 1 + \\frac{1}{2} \\times 0{,}02 = 1{,}01$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":587,"term":"cercle trigonométrique","sense":null,"grade":"1_SPE","tags":["trigonométrie","géométrie"],"definitions":{"items":[{"grade":"1_SPE","content":"Dans un repère orthonormé $(O ; I, J)$, cercle de centre $O$ et de rayon $1$, parcouru dans le sens inverse des aiguilles d'une montre (sens direct). En y enroulant la droite des réels à partir de $I$, on associe à chaque réel $x$ un point $M$ du cercle, de coordonnées $(\\cos x ; \\sin x)$. Ex : au réel $\\pi$ correspond le point $(-1 ; 0)$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":588,"term":"dérivable","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Une fonction $f$ est dérivable en $a$ si son taux de variation $\\frac{f(a + h) - f(a)}{h}$ a une limite finie quand $h$ tend vers $0$ ; cette limite est le nombre dérivé $f'(a)$. Elle est dérivable sur un intervalle si elle l'est en chaque nombre de cet intervalle. Ex : la fonction racine carrée n'est pas dérivable en $0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":589,"term":"échantillon","sense":null,"grade":"1_SPE","tags":["probabilités","statistiques"],"definitions":{"items":[{"grade":"1_SPE","content":"Liste des $n$ résultats obtenus en répétant $n$ fois, de façon indépendante, la même expérience aléatoire ; $n$ est la taille de l'échantillon. Ex : $50$ lancers d'un dé forment un échantillon de taille $50$, dont la moyenne permet d'estimer l'espérance du résultat d'un lancer.","sharedWith":["1_TECHNO"]},{"grade":"T_SPE","content":"Un échantillon de taille $n$ d'une loi de probabilité est une liste $(X_1, \\ldots, X_n)$ de variables aléatoires indépendantes qui suivent toutes cette loi ; sa moyenne est $M_n = \\frac{X_1 + \\cdots + X_n}{n}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_TECHNO"]},{"position":590,"term":"fonction polynôme du second degré","sense":null,"grade":"1_SPE","tags":["fonctions","équations"],"definitions":{"items":[{"grade":"1_SPE","content":"Fonction définie sur $\\mathbb{R}$ par $f(x) = ax^2 + bx + c$, où $a$, $b$, $c$ sont des réels avec $a \\neq 0$ ; sa courbe est une parabole. Ex : $f(x) = 2x^2 - 3x + 1 = (2x - 1)(x - 1)$, dont les racines sont $\\frac{1}{2}$ et $1$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":591,"term":"formule d'Al-Kashi","sense":null,"grade":"1_SPE","tags":["géométrie","trigonométrie"],"definitions":{"items":[{"grade":"1_SPE","content":"Dans tout triangle $ABC$ : $BC^2 = AB^2 + AC^2 - 2 \\times AB \\times AC \\times \\cos\\widehat{BAC}$. Elle généralise le théorème de Pythagore : si l'angle $\\widehat{BAC}$ est droit, son cosinus est nul. Ex : si $AB = 5$, $AC = 3$ et $\\widehat{BAC} = 60°$, alors $BC^2 = 25 + 9 - 15 = 19$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":592,"term":"formule des probabilités totales","sense":null,"grade":"1_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"1_SPE","content":"Si les évènements $A_1, \\ldots, A_n$ forment une partition de l'univers, alors pour tout évènement $B$ : $P(B) = P(A_1 \\cap B) + \\cdots + P(A_n \\cap B)$. Avec un évènement $A$ tel que $0 < P(A) < 1$ : $P(B) = P(A) \\times P_A(B) + P(\\bar{A}) \\times P_{\\bar{A}}(B)$.","sharedWith":["1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_TECHNO"]},{"position":593,"term":"liste","sense":"informatique","grade":"2","tags":["transversal"],"definitions":{"items":[{"grade":"2","content":"En informatique, suite ordonnée de valeurs rangées sous un même nom ; une même valeur peut y apparaître plusieurs fois. En Python, on l'écrit entre crochets : « notes = [12, 15, 9, 15] »."},{"grade":"1_SPE","content":"Chaque élément d'une liste est repéré par son indice, qui commence à $0$ : si « L = [12, 15, 9] », alors « L[0] » vaut $12$. On crée une liste en extension (« [1, 4, 9] »), par ajouts successifs (« L.append(16) ») ou en compréhension (« [k**2 for k in range(4)] » donne « [0, 1, 4, 9] »).","sharedWith":["1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":false,"derived_from":null,"see_also":null,"shared_with":[]},{"position":594,"term":"nombre e","sense":null,"grade":"1_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"1_SPE","content":"Image de $1$ par la fonction exponentielle : $e = \\exp(1) \\approx 2{,}718$. On note $e^x = \\exp(x)$ pour tout réel $x$, ce qui prolonge les puissances : $e^2 = e \\times e$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":595,"term":"vecteurs orthogonaux","sense":null,"grade":"1_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"1_SPE","content":"Deux vecteurs non nuls sont orthogonaux si leurs directions sont perpendiculaires ; par convention, le vecteur nul est orthogonal à tout vecteur. Deux vecteurs $\\vec{u}$ et $\\vec{v}$ sont orthogonaux si et seulement si $\\vec{u} \\cdot \\vec{v} = 0$. Ex : en base orthonormée, $\\vec{u}(2 ; 3)$ et $\\vec{v}(-3 ; 2)$ sont orthogonaux car $2 \\times (-3) + 3 \\times 2 = 0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":596,"term":"paramètre","sense":null,"grade":"5","tags":["calcul-littéral","transversal"],"definitions":{"items":[{"grade":"5","content":"Dans un programme, valeur que l'on peut changer pour modifier le résultat, sans toucher aux instructions. Ex : dans un programme qui trace un carré, la longueur du côté peut être un paramètre."},{"grade":"1_SPE","content":"Lettre qui désigne un nombre fixé pendant l'étude d'un problème, mais que l'on peut faire varier d'un problème à l'autre ; ce n'est ni l'inconnue ni la variable. Ex : dans l'équation $x^2 = m$, d'inconnue $x$, le paramètre $m$ décide du nombre de solutions : deux si $m > 0$, une si $m = 0$, aucune si $m < 0$.","sharedWith":["1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":597,"term":"partition","sense":null,"grade":"1_SPE","tags":["probabilités","logique"],"definitions":{"items":[{"grade":"1_SPE","content":"Des évènements $A_1, \\ldots, A_n$, non vides, forment une partition de l'univers $\\Omega$ s'ils sont deux à deux incompatibles (sans issue commune) et si leur réunion est $\\Omega$ : chaque issue appartient à un et un seul d'entre eux. Ex : pour un dé, $\\{1, 2\\}$, $\\{3\\}$ et $\\{4, 5, 6\\}$ forment une partition de $\\Omega = \\{1, 2, 3, 4, 5, 6\\}$."}]},"exemples":null,"history":null,"image":null,"synonyms":["système complet d'évènements","système complet d'événements"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":598,"term":"projeté orthogonal","sense":null,"grade":"1_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"1_SPE","content":"Le projeté orthogonal d'un point $M$ sur une droite $d$ est le point $H$ de $d$ tel que la droite $(MH)$ soit perpendiculaire à $d$ ($H = M$ si $M$ est sur $d$). C'est le point de $d$ le plus proche de $M$ : la distance de $M$ à la droite $d$ est $MH$."},{"grade":"T_SPE","content":"Dans l'espace, le projeté orthogonal d'un point $M$ sur un plan $\\mathcal{P}$ est le point $H$ de $\\mathcal{P}$ tel que $\\overrightarrow{MH}$ soit nul ou normal à $\\mathcal{P}$ ; c'est le point de $\\mathcal{P}$ le plus proche de $M$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":599,"term":"seuil","sense":null,"grade":"1_SPE","tags":["suites","transversal"],"definitions":{"items":[{"grade":"1_SPE","content":"Valeur fixée à l'avance qu'une quantité doit atteindre ou dépasser ; un problème de seuil consiste à chercher à partir de quel rang (ou de quel moment) c'est le cas. Ex : pour $u_n = 1{,}05^n$, le plus petit entier $n$ tel que $u_n > 2$ est $15$ ; un algorithme de seuil le trouve en calculant les termes tant que $u_n \\leq 2$.","sharedWith":["1_GEN","1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_GEN","1_TECHNO"]},{"position":600,"term":"vecteur normal","sense":null,"grade":"1_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"1_SPE","content":"Un vecteur normal à une droite $d$ est un vecteur non nul orthogonal à un vecteur directeur de $d$. En repère orthonormé, le vecteur $\\vec{n}(a ; b)$ est normal à la droite d'équation $ax + by + c = 0$."},{"grade":"T_SPE","content":"Un vecteur normal à un plan $\\mathcal{P}$ est un vecteur non nul orthogonal à deux vecteurs non colinéaires de la direction de $\\mathcal{P}$, donc à tout vecteur de cette direction. En repère orthonormé, $\\vec{n}(a ; b ; c)$ est normal au plan d'équation $ax + by + cz + d = 0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":601,"term":"combinaison linéaire","sense":null,"grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Un vecteur $\\vec{w}$ est une combinaison linéaire de $\\vec{u}$ et $\\vec{v}$ s'il existe deux réels $a$ et $b$ tels que $\\vec{w} = a\\vec{u} + b\\vec{v}$. Si $\\vec{u}$ et $\\vec{v}$ ne sont pas colinéaires, tout vecteur du plan s'écrit ainsi, d'une seule façon. Ex : dans un parallélogramme $ABCD$, $\\overrightarrow{AC} = \\overrightarrow{AB} + \\overrightarrow{AD}$."},{"grade":"T_SPE","content":"Dans l'espace, une combinaison linéaire de $\\vec{u}$, $\\vec{v}$, $\\vec{w}$ est un vecteur $a\\vec{u} + b\\vec{v} + c\\vec{w}$, avec $a$, $b$, $c$ réels ; si ces trois vecteurs ne sont pas coplanaires, tout vecteur de l'espace s'écrit ainsi, d'une seule façon."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":602,"term":"croissance comparée","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Résultats qui comparent la vitesse à laquelle des fonctions tendent vers l'infini : en $+\\infty$, l'exponentielle l'emporte sur toute puissance $x^n$, qui l'emporte elle-même sur le logarithme. Pour tout entier $n \\geq 1$ : $\\lim_{x \\to +\\infty} \\frac{e^x}{x^n} = +\\infty$, $\\lim_{x \\to +\\infty} \\frac{\\ln(x)}{x^n} = 0$, et $x^n \\ln(x)$ tend vers $0$ quand $x$ tend vers $0$ par valeurs positives."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":603,"term":"dichotomie","sense":null,"grade":"2","tags":["fonctions","transversal"],"definitions":{"items":[{"grade":"2","content":"Méthode qui encadre une valeur cherchée en coupant l'intervalle en deux à chaque étape et en gardant la moitié qui la contient : l'amplitude de l'encadrement est divisée par $2$ à chaque étape. Ex : pour approcher la solution positive de $x^2 = 2$, on part de $[1 ; 2]$ ; comme $1{,}5^2 > 2$, on garde $[1 ; 1{,}5]$, et ainsi de suite."},{"grade":"T_SPE","content":"Si $f$ est continue et strictement monotone sur $[a ; b]$, avec $f(a)$ et $f(b)$ de signes contraires, l'équation $f(x) = 0$ a une unique solution dans $[a ; b]$ ; la dichotomie l'encadre en gardant à chaque étape la moitié de l'intervalle aux bornes de laquelle $f$ change de signe."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":604,"term":"disjoints","sense":null,"grade":"T_SPE","tags":["logique","probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Deux ensembles sont disjoints s'ils n'ont aucun élément commun : $A \\cap B = \\varnothing$. Plusieurs ensembles sont deux à deux disjoints si deux quelconques d'entre eux sont disjoints ; pour des évènements, on dit incompatibles. Ex : l'ensemble des entiers pairs et celui des entiers impairs sont disjoints."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":605,"term":"inégalité de Bienaymé-Tchebychev","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Pour une variable aléatoire $X$ d'espérance $\\mu$ et de variance $V$, et pour tout réel $\\delta > 0$ : $P(|X - \\mu| \\geq \\delta) \\leq \\frac{V}{\\delta^2}$. Elle dit qu'un grand écart à l'espérance est peu probable : avec l'écart type $\\sigma$ et $\\delta = 2\\sigma$, cette probabilité vaut au plus $\\frac{1}{4}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":606,"term":"intégration par parties","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Si $u$ et $v$ sont dérivables sur $[a ; b]$, avec $u'$ et $v'$ continues : $\\int_a^b u(x)v'(x)\\,\\mathrm{d}x = \\big[u(x)v(x)\\big]_a^b - \\int_a^b u'(x)v(x)\\,\\mathrm{d}x$. Ex : avec $u(x) = x$ et $v(x) = e^x$, $\\int_0^1 xe^x\\,\\mathrm{d}x = e - \\int_0^1 e^x\\,\\mathrm{d}x = e - (e - 1) = 1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":607,"term":"suite majorée","sense":null,"grade":"T_SPE","tags":["suites"],"definitions":{"items":[{"grade":"T_SPE","content":"Une suite $(u_n)$ est majorée s'il existe un réel $M$ tel que, pour tout entier $n$, $u_n \\leq M$ ; elle est minorée s'il existe un réel $m$ tel que, pour tout $n$, $u_n \\geq m$ ; elle est bornée si elle est à la fois majorée et minorée. Ex : la suite $u_n = \\frac{1}{n + 1}$ est bornée, car $0 < u_n \\leq 1$ pour tout $n$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":608,"term":"k-uplet","sense":null,"grade":"T_SPE","tags":["logique","probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Liste ordonnée $(x_1, x_2, \\ldots, x_k)$ de $k$ éléments, pas forcément distincts ; on dit aussi $k$-liste. Un $2$-uplet est un couple, un $3$-uplet un triplet, et un ensemble à $n$ éléments donne $n^k$ $k$-uplets. Ex : il y a $10^4 = 10\\,000$ codes à $4$ chiffres."}]},"exemples":null,"history":null,"image":null,"synonyms":["n-uplet","k-liste"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":609,"term":"droites orthogonales","sense":null,"grade":"T_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"T_SPE","content":"Deux droites de l'espace sont orthogonales si un vecteur directeur de l'une est orthogonal à un vecteur directeur de l'autre. Elles ne sont pas forcément sécantes ; orthogonales et sécantes, elles sont perpendiculaires. Ex : dans un cube $ABCDEFGH$, les droites $(AB)$ et $(FG)$ sont orthogonales, mais pas perpendiculaires."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":610,"term":"fonction périodique","sense":null,"grade":"T_SPE","tags":["fonctions","trigonométrie"],"definitions":{"items":[{"grade":"T_SPE","content":"Une fonction $f$ définie sur $\\mathbb{R}$ est périodique de période $T$ (avec $T > 0$) si, pour tout réel $x$, $f(x + T) = f(x)$ : sa courbe se reproduit à l'identique par translation de $T$ le long de l'axe des abscisses. Ex : $\\cos$ et $\\sin$ sont périodiques de période $2\\pi$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":611,"term":"principe multiplicatif","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Le nombre d'éléments d'un produit cartésien d'ensembles finis est le produit de leurs nombres d'éléments : $\\mathrm{Card}(A \\times B) = \\mathrm{Card}(A) \\times \\mathrm{Card}(B)$. Ex : avec $3$ entrées et $4$ plats, on peut composer $3 \\times 4 = 12$ menus « entrée + plat »."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":612,"term":"principe additif","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Le nombre d'éléments d'une réunion d'ensembles finis deux à deux disjoints est la somme de leurs nombres d'éléments : si $A \\cap B = \\varnothing$, alors $\\mathrm{Card}(A \\cup B) = \\mathrm{Card}(A) + \\mathrm{Card}(B)$. Ex : une classe de $14$ filles et $16$ garçons compte $30$ élèves."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":613,"term":"produit cartésien","sense":null,"grade":"2","tags":["logique"],"definitions":{"items":[{"grade":"2","content":"Le produit cartésien $A \\times B$ de deux ensembles $A$ et $B$ est l'ensemble de tous les couples $(a ; b)$ tels que $a \\in A$ et $b \\in B$. Ex : si $A = \\{1, 2\\}$ et $B = \\{\\text{P}, \\text{F}\\}$, alors $A \\times B = \\{(1 ; \\text{P}), (1 ; \\text{F}), (2 ; \\text{P}), (2 ; \\text{F})\\}$ ; le plan repéré correspond à $\\mathbb{R} \\times \\mathbb{R}$, noté $\\mathbb{R}^2$."},{"grade":"T_SPE","content":"Plus généralement, $A_1 \\times A_2 \\times \\cdots \\times A_k$ est l'ensemble des $k$-uplets $(a_1, a_2, \\ldots, a_k)$ tels que $a_1 \\in A_1$, …, $a_k \\in A_k$ ; si tous ces ensembles sont égaux à $A$, on le note $A^k$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":614,"term":"représentation paramétrique","sense":null,"grade":"T_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"T_SPE","content":"La droite de l'espace passant par $A(x_A ; y_A ; z_A)$ et de vecteur directeur $\\vec{u}(a ; b ; c)$ est l'ensemble des points $M(x ; y ; z)$ tels que $x = x_A + ta$, $y = y_A + tb$, $z = z_A + tc$, où $t$ décrit $\\mathbb{R}$ : ces trois égalités forment une représentation paramétrique de la droite, de paramètre $t$. Elles traduisent $\\overrightarrow{AM} = t\\vec{u}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":615,"term":"symbole somme","sense":null,"grade":"T_SPE","tags":["suites","transversal"],"definitions":{"items":[{"grade":"T_SPE","content":"Le symbole $\\sum$ (sigma majuscule) écrit une somme de façon concise : $\\sum_{k=1}^{n} u_k = u_1 + u_2 + \\cdots + u_n$, où l'indice $k$ prend toutes les valeurs entières de $1$ à $n$. Ex : $\\sum_{k=1}^{4} k^2 = 1 + 4 + 9 + 16 = 30$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":616,"term":"tétraèdre","sense":null,"grade":"T_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"T_SPE","content":"Solide formé de quatre faces triangulaires : c'est une pyramide à base triangulaire. Il a $4$ sommets, $6$ arêtes et $4$ faces ; il est régulier si ses quatre faces sont des triangles équilatéraux."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":617,"term":"théorème des gendarmes","sense":null,"grade":"T_SPE","tags":["suites","fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Si, à partir d'un certain rang, $v_n \\leq u_n \\leq w_n$, et si les suites $(v_n)$ et $(w_n)$ convergent vers un même réel $\\ell$, alors $(u_n)$ converge aussi vers $\\ell$ ; il existe un énoncé analogue pour les fonctions. Ex : pour $n \\geq 1$, $-\\frac{1}{n} \\leq \\frac{(-1)^n}{n} \\leq \\frac{1}{n}$, donc $\\frac{(-1)^n}{n}$ tend vers $0$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":618,"term":"triangle de Pascal","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Tableau triangulaire des coefficients binomiaux : la ligne $n$ contient $\\binom{n}{0}, \\binom{n}{1}, \\ldots, \\binom{n}{n}$. Chaque nombre intérieur est la somme des deux nombres voisins de la ligne précédente, d'après la relation de Pascal $\\binom{n}{k} + \\binom{n}{k+1} = \\binom{n+1}{k+1}$ (pour $0 \\leq k \\leq n - 1$). Ex : la ligne $4$ est $1$, $4$, $6$, $4$, $1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":619,"term":"valeur moyenne","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"La valeur moyenne d'une fonction $f$ continue sur $[a ; b]$ (avec $a < b$) est le nombre $\\mu = \\frac{1}{b - a}\\int_a^b f(x)\\,\\mathrm{d}x$. Si $f$ est positive, le rectangle de base $[a ; b]$ et de hauteur $\\mu$ a la même aire que le domaine situé sous sa courbe. Ex : sur $[0 ; 2]$, la valeur moyenne de $x \\mapsto x$ est $1$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":620,"term":"vecteurs coplanaires","sense":null,"grade":"T_SPE","tags":["géométrie"],"definitions":{"items":[{"grade":"T_SPE","content":"Des vecteurs de l'espace sont coplanaires si, représentés à partir d'un même point $O$, ils ont leurs extrémités dans un même plan passant par $O$. Si $\\vec{u}$ et $\\vec{v}$ ne sont pas colinéaires, $\\vec{u}$, $\\vec{v}$, $\\vec{w}$ sont coplanaires si et seulement s'il existe deux réels $a$ et $b$ tels que $\\vec{w} = a\\vec{u} + b\\vec{v}$. Ex : dans un cube $ABCDEFGH$, $\\overrightarrow{AB}$, $\\overrightarrow{AD}$, $\\overrightarrow{AC}$ sont coplanaires, mais pas $\\overrightarrow{AB}$, $\\overrightarrow{AD}$, $\\overrightarrow{AE}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":621,"term":"droite de Mayer","sense":null,"grade":"1_GEN","tags":["statistiques"],"definitions":{"items":[{"grade":"1_GEN","content":"Droite d'ajustement d'un nuage de points : on range les points selon leurs abscisses, on les partage en deux groupes de même effectif (à un point près), puis on trace la droite qui passe par les points moyens $G_1$ et $G_2$ des deux groupes. Elle passe aussi par le point moyen $G$ du nuage entier."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":622,"term":"interpolation","sense":null,"grade":"1_GEN","tags":["statistiques"],"definitions":{"items":[{"grade":"1_GEN","content":"Estimation d'une valeur inconnue située entre des valeurs connues, à l'aide d'un modèle comme une droite d'ajustement ; si la valeur estimée est en dehors de la plage des données, on parle d'extrapolation, moins fiable. Ex : connaissant la population d'une ville en 2000 et en 2020, estimer celle de 2010 est une interpolation, celle de 2040 une extrapolation.","sharedWith":["1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_TECHNO"]},{"position":623,"term":"méthode des moindres carrés","sense":null,"grade":"1_GEN","tags":["statistiques"],"definitions":{"items":[{"grade":"1_GEN","content":"Méthode d'ajustement affine qui choisit, parmi les droites d'équation $y = ax + b$, celle qui rend la plus petite possible la somme des carrés des écarts verticaux $\\big(y_i - (ax_i + b)\\big)^2$ entre les points du nuage et la droite. Cette droite passe par le point moyen du nuage ; la calculatrice ou le tableur donne $a$ et $b$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":624,"term":"taux d'évolution moyen","sense":null,"grade":"1_GEN","tags":["proportionnalité","puissances"],"definitions":{"items":[{"grade":"1_GEN","content":"Taux $t$ qui, appliqué $n$ fois de suite, produit la même évolution globale que $n$ évolutions successives : si le coefficient multiplicateur global est $C$, alors $(1 + t)^n = C$, donc $t = C^{1/n} - 1$. Ex : une population qui double en $5$ ans ($C = 2$) augmente en moyenne de $2^{1/5} - 1 \\approx 14{,}9\\,\\%$ par an."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":625,"term":"suite minorée","sense":null,"grade":"T_SPE","tags":["suites"],"definitions":null,"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":"suite majorée","see_also":null,"shared_with":[]},{"position":626,"term":"suite bornée","sense":null,"grade":"T_SPE","tags":["suites"],"definitions":null,"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":"suite majorée","see_also":null,"shared_with":[]},{"position":627,"term":"extrapolation","sense":null,"grade":"1_GEN","tags":["statistiques"],"definitions":null,"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":"interpolation","see_also":null,"shared_with":["1_TECHNO"]},{"position":628,"term":"ensemble des solutions","sense":null,"grade":"2","tags":["équations"],"definitions":{"items":[{"grade":"2","content":"Ensemble de tous les nombres qui vérifient une équation ou une inéquation ; on le note souvent $S$. Ex : l'équation $2x + 6 = 0$ a pour ensemble des solutions $S = \\{-3\\}$, l'inéquation $x > 2$ a pour ensemble des solutions l'intervalle $]2 ; +\\infty[$, et une équation sans solution a pour ensemble des solutions l'ensemble vide $\\varnothing$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":629,"term":"représentant","sense":"vecteur","grade":"2","tags":["géométrie"],"definitions":{"items":[{"grade":"2","content":"Un représentant d'un vecteur est une flèche qui le dessine, d'une origine à une extrémité. Un vecteur a une infinité de représentants, tous de même direction, de même sens et de même longueur. Ex : si $ABDC$ est un parallélogramme, $\\overrightarrow{AB}$ et $\\overrightarrow{CD}$ sont deux représentants du même vecteur."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":630,"term":"équilibré","sense":null,"grade":"5","tags":["probabilités"],"definitions":{"items":[{"grade":"5","content":"Se dit d'un dé, d'une pièce ou d'une roue qui n'avantage aucune issue : chaque issue a la même chance de se produire. Ex : avec un dé équilibré à six faces, chaque face a la probabilité $\\frac{1}{6}$ d'apparaître."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":["équilibrée"],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":631,"term":"indiscernable","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Se dit d'objets que l'on ne peut pas distinguer : des boules indiscernables au toucher ont toutes la même chance d'être tirées quand on en choisit une sans regarder."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":632,"term":"urne","sense":null,"grade":"CM1","tags":["probabilités"],"definitions":{"items":[{"grade":"CM1","content":"Boîte ou sac dont on tire des objets au hasard, sans regarder, dans les problèmes de probabilités. Ex : une urne contient $3$ boules rouges et $2$ boules bleues ; on en tire une au hasard."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":633,"term":"tirage avec remise","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Tirages successifs où l'objet tiré est remis dans l'urne avant le tirage suivant : la composition de l'urne ne change pas, et les tirages sont indépendants. Ex : avec remise, on peut tirer deux fois la même boule."}]},"exemples":null,"history":null,"image":null,"synonyms":["avec remise"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":634,"term":"tirage sans remise","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Tirages successifs où l'objet tiré n'est pas remis dans l'urne : la composition de l'urne change à chaque tirage, et les tirages ne sont pas indépendants. Ex : sans remise, on ne peut pas tirer deux fois la même boule."}]},"exemples":null,"history":null,"image":null,"synonyms":["sans remise"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":635,"term":"intérêts composés","sense":null,"grade":"1_GEN","tags":["proportionnalité","suites"],"definitions":{"items":[{"grade":"1_GEN","content":"Placement où les intérêts de chaque année s'ajoutent au capital et rapportent à leur tour des intérêts : le capital est multiplié chaque année par le même nombre. Ex : à $3\\,\\%$ par an, un capital de $1\\,000$ € devient $1\\,000 \\times 1{,}03^n$ € au bout de $n$ années.","sharedWith":["1_SPE"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_SPE"]},{"position":636,"term":"ajustement affine","sense":null,"grade":"1_GEN","tags":["statistiques"],"definitions":{"items":[{"grade":"1_GEN","content":"Remplacer un nuage de points par une droite qui en passe au plus près, pour décrire la tendance et faire des prévisions (interpolation, extrapolation). Ex : la droite de Mayer et la droite des moindres carrés sont deux ajustements affines.","sharedWith":["1_TECHNO"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["1_TECHNO"]},{"position":637,"term":"inégalité de concentration","sense":null,"grade":"T_SPE","tags":["probabilités"],"definitions":{"items":[{"grade":"T_SPE","content":"Si $M_n$ est la moyenne d'un échantillon de taille $n$ d'une variable aléatoire d'espérance $\\mu$ et de variance $V$, alors pour tout réel $\\delta > 0$ : $P(|M_n - \\mu| \\geq \\delta) \\leq \\frac{V}{n\\delta^2}$. Plus l'échantillon est grand, plus sa moyenne a de chances d'être proche de $\\mu$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":638,"term":"méthode des rectangles","sense":null,"grade":"T_SPE","tags":["fonctions"],"definitions":{"items":[{"grade":"T_SPE","content":"Méthode qui approche une intégrale par une somme d'aires de rectangles : on découpe $[a ; b]$ en $n$ intervalles de même largeur $\\frac{b - a}{n}$ et, sur chacun, on prend un rectangle dont la hauteur est une valeur de la fonction (à une extrémité de l'intervalle). Plus $n$ est grand, meilleure est l'approximation.","sharedWith":["T_COMP"]}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":["T_COMP"]},{"position":639,"term":"escalier","sense":"suite","grade":"1_SPE","tags":["suites"],"definitions":{"items":[{"grade":"1_SPE","content":"Construction graphique des termes d'une suite définie par $u_{n+1} = f(u_n)$ : depuis $u_0$ sur l'axe des abscisses, on va verticalement jusqu'à la courbe de $f$, puis horizontalement jusqu'à la droite d'équation $y = x$, ce qui donne $u_1$ en abscisse, et on recommence. Selon la fonction, le tracé forme un escalier ou une spirale."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":640,"term":"nombre complexe","sense":null,"grade":"T_EXP","tags":["transversal"],"definitions":{"items":[{"grade":"T_EXP","content":"Nombre de la forme $a + ib$, où $a$ et $b$ sont des réels et $i$ un nombre tel que $i^2 = -1$ ; $a$ est sa partie réelle, $b$ sa partie imaginaire. Ex : $3 - 2i$ est un nombre complexe ; les réels sont les nombres complexes de partie imaginaire nulle."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":641,"term":"forme algébrique","sense":null,"grade":"T_EXP","tags":["calcul-littéral"],"definitions":{"items":[{"grade":"T_EXP","content":"Écriture d'un nombre complexe sous la forme $z = a + ib$, avec $a$ et $b$ réels. Elle est unique : deux nombres complexes sont égaux si et seulement s'ils ont la même partie réelle et la même partie imaginaire."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":642,"term":"affixe","sense":null,"grade":"T_EXP","tags":["géométrie"],"definitions":{"items":[{"grade":"T_EXP","content":"Dans un plan muni d'un repère orthonormé, l'affixe du point $M(a ; b)$ est le nombre complexe $z = a + ib$ ; de même, l'affixe du vecteur $\\vec{w}(a ; b)$ est $a + ib$. Ex : le point $A(2 ; -1)$ a pour affixe $2 - i$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":643,"term":"module","sense":"nombre complexe","grade":"T_EXP","tags":["géométrie"],"definitions":{"items":[{"grade":"T_EXP","content":"Le module de $z = a + ib$ est le réel positif $|z| = \\sqrt{a^2 + b^2}$ : c'est la distance entre l'origine du repère et le point d'affixe $z$. Ex : $|3 + 4i| = 5$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":644,"term":"argument","sense":"nombre complexe","grade":"T_EXP","tags":["géométrie","trigonométrie"],"definitions":{"items":[{"grade":"T_EXP","content":"Dans un repère orthonormé direct $(O ; \\vec{u}, \\vec{v})$, un argument d'un nombre complexe $z$ non nul est une mesure, en radians, de l'angle orienté $(\\vec{u}, \\overrightarrow{OM})$, où $M$ est le point d'affixe $z$. Il est défini à $2\\pi$ près ; l'argument principal est celui de $]-\\pi ; \\pi]$. Ex : $i$ a pour argument principal $\\frac{\\pi}{2}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":645,"term":"forme exponentielle","sense":null,"grade":"T_EXP","tags":["calcul-littéral","trigonométrie"],"definitions":{"items":[{"grade":"T_EXP","content":"Écriture d'un nombre complexe non nul sous la forme $z = re^{i\\theta}$, où $r = |z|$ est son module et $\\theta$ un argument. Ex : $1 + i = \\sqrt{2}\\,e^{i\\frac{\\pi}{4}}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":646,"term":"matrice","sense":null,"grade":"T_EXP","tags":["transversal"],"definitions":{"items":[{"grade":"T_EXP","content":"Tableau de nombres réels rangés en $n$ lignes et $p$ colonnes : on dit qu'elle est de taille $n \\times p$. Une matrice carrée a autant de lignes que de colonnes ; une matrice colonne n'a qu'une colonne. Ex : $\\begin{pmatrix} 1 & 2 \\\\ 0 & -3 \\end{pmatrix}$ est une matrice carrée de taille $2 \\times 2$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":647,"term":"graphe","sense":null,"grade":"T_EXP","tags":["transversal"],"definitions":{"items":[{"grade":"T_EXP","content":"Ensemble de points, appelés sommets, reliés par des lignes, appelées arêtes. Dans un graphe orienté, les arêtes ont un sens ; dans un graphe pondéré, chaque arête porte un nombre, son poids. Ex : un plan de métro, dont les stations sont les sommets."}]},"exemples":null,"history":null,"image":null,"synonyms":["graphe orienté","graphe pondéré"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":648,"term":"chaîne de Markov","sense":null,"grade":"T_EXP","tags":["probabilités"],"definitions":{"items":[{"grade":"T_EXP","content":"Suite de variables aléatoires $(X_n)$ qui décrit l'évolution d'un système entre quelques états : la probabilité de passer d'un état à un autre ne dépend que de l'état présent. On la représente par un graphe orienté pondéré et par sa matrice de transition. Ex : chaque jour, le temps est « beau » ou « pluvieux », avec des probabilités qui dépendent du temps de la veille."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":649,"term":"loi uniforme","sense":null,"grade":"T_COMP","tags":["probabilités"],"definitions":{"items":[{"grade":"T_COMP","content":"Loi d'une variable aléatoire dont toutes les valeurs ont la même chance : sur $\\{1, 2, \\ldots, n\\}$, chaque valeur a la probabilité $\\frac{1}{n}$ et l'espérance vaut $\\frac{n + 1}{2}$. Sur un intervalle $[a ; b]$, c'est une loi à densité, de densité constante égale à $\\frac{1}{b - a}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":650,"term":"fonction de densité","sense":null,"grade":"T_COMP","tags":["probabilités","fonctions"],"definitions":{"items":[{"grade":"T_COMP","content":"Une variable aléatoire $X$ suit une loi à densité $f$ sur un intervalle $I$ si $f$ est continue et positive sur $I$, avec une aire totale égale à $1$ sous sa courbe, et si $P(c \\leq X \\leq d) = \\int_c^d f(x)\\,\\mathrm{d}x$ pour tout intervalle $[c ; d]$ inclus dans $I$ : une probabilité est une aire."}]},"exemples":null,"history":null,"image":null,"synonyms":["densité","loi à densité"],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":651,"term":"loi exponentielle","sense":null,"grade":"T_COMP","tags":["probabilités"],"definitions":{"items":[{"grade":"T_COMP","content":"Loi à densité de paramètre $\\lambda > 0$ sur $[0 ; +\\infty[$, de densité $f(x) = \\lambda e^{-\\lambda x}$ : $P(X \\leq t) = 1 - e^{-\\lambda t}$ et l'espérance vaut $\\frac{1}{\\lambda}$. Elle modélise des durées de vie sans vieillissement, comme celle d'un composant électronique."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":652,"term":"fonction exponentielle","sense":"de base a","grade":"1_GEN","tags":["fonctions","puissances"],"definitions":{"items":[{"grade":"1_GEN","content":"Pour un réel $a > 0$, la fonction $x \\mapsto a^x$ prolonge les puissances : $a^0 = 1$, $a^1 = a$ et $a^{x + y} = a^x \\times a^y$. Elle est croissante si $a > 1$ et décroissante si $0 < a < 1$ ; elle modélise une croissance ou une décroissance exponentielle. Ex : $2^{0{,}5} = \\sqrt{2}$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":null,"shared_with":[]},{"position":653,"term":"chiffre","sense":"cryptographie","grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Méthode pour écrire un message en secret, que seul celui qui connaît la clé peut relire. Ex : le chiffre de César, le chiffre de Vigenère."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":false,"derived_from":null,"see_also":{"label":"Le Cabinet Noir de Turingrad","path":"/chiffrement"},"shared_with":[]},{"position":654,"term":"chiffrer","sense":null,"grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Transformer un message à l’aide d’une clé pour le rendre illisible. On évite « crypter » : chiffrer sans clé n’aurait pas de sens."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le Cabinet Noir de Turingrad","path":"/chiffrement"},"shared_with":[]},{"position":655,"term":"déchiffrer","sense":null,"grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Retrouver le message clair à partir du message chiffré, **en connaissant** la clé."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le Cabinet Noir de Turingrad","path":"/chiffrement"},"shared_with":[]},{"position":656,"term":"décrypter","sense":null,"grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Retrouver le message clair **sans connaître** la clé, par exemple grâce à l’analyse de fréquences."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Les Dépêches du Czar","path":"/chiffrement/depeches"},"shared_with":[]},{"position":657,"term":"clé","sense":"cryptographie","grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Information secrète qui règle un chiffre : le décalage du chiffre de César, le mot-clé du chiffre de Vigenère…"}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le Cabinet Noir de Turingrad","path":"/chiffrement"},"shared_with":[]},{"position":658,"term":"chiffre de César","sense":null,"grade":"6","tags":["cryptographie"],"definitions":{"items":[{"grade":"6","content":"Chiffre qui décale chaque lettre d’un même nombre de rangs dans l’alphabet, en repartant au début après Z."}]},"exemples":{"items":[{"grade":"6","content":"Avec un décalage de $3$, A devient D et Y devient B."}]},"history":"L’historien Suétone raconte que Jules César décalait les lettres de ses messages secrets de trois rangs.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre de César","path":"/chiffrement/cesar"},"shared_with":[]},{"position":659,"term":"analyse de fréquences","sense":null,"grade":"5","tags":["cryptographie","statistiques"],"definitions":{"items":[{"grade":"5","content":"Méthode de décryptage qui compare la fréquence des lettres d’un message chiffré à celle de la langue. En français, la lettre la plus fréquente est presque toujours le E."}]},"exemples":null,"history":"Décrite par le savant arabe Al-Kindi au IXᵉ siècle.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"La substitution","path":"/chiffrement/substitution"},"shared_with":[]},{"position":660,"term":"chiffre de Vigenère","sense":null,"grade":"2","tags":["cryptographie"],"definitions":{"items":[{"grade":"2","content":"Chiffre dont le décalage change à chaque lettre, selon les lettres d’un mot-clé répété tout au long du message."}]},"exemples":null,"history":"Publié par Giovan Battista Bellaso en 1553, popularisé par Blaise de Vigenère en 1586, il fut surnommé « le chiffre indéchiffrable » jusqu’à la méthode de Kasiski (1863).","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre de Vigenère","path":"/chiffrement/vigenere"},"shared_with":[]},{"position":661,"term":"méthode de Kasiski","sense":null,"grade":"2","tags":["cryptographie"],"definitions":{"items":[{"grade":"2","content":"Méthode pour trouver la longueur de la clé d’un chiffre de Vigenère : les écarts entre deux séquences répétées du message chiffré sont souvent des multiples de cette longueur."}]},"exemples":null,"history":"Publiée par l’officier prussien Friedrich Kasiski en 1863.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre de Vigenère","path":"/chiffrement/vigenere"},"shared_with":[]},{"position":662,"term":"indice de coïncidence","sense":null,"grade":"2","tags":["cryptographie","probabilités"],"definitions":{"items":[{"grade":"2","content":"Probabilité que deux lettres prises au hasard dans un texte soient identiques : environ $0{,}078$ en français, $0{,}038$ pour des lettres tirées au hasard."}]},"exemples":null,"history":"Introduit par le cryptologue américain William Friedman dans les années 1920.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre de Vigenère","path":"/chiffrement/vigenere"},"shared_with":[]},{"position":663,"term":"congruence","sense":null,"grade":"T_EXP","tags":["entiers","arithmétique","cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"$a \\equiv b \\pmod{n}$ signifie que $n$ divise $a - b$ : $a$ et $b$ ont le même reste dans la division euclidienne par $n$."}]},"exemples":{"items":[{"grade":"T_EXP","content":"$27 \\equiv 1 \\pmod{26}$, car $27 - 1 = 26$."}]},"history":null,"image":null,"synonyms":["modulo"],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre affine","path":"/chiffrement/affine"},"shared_with":[]},{"position":664,"term":"inverse modulaire","sense":null,"grade":"T_EXP","tags":["entiers","arithmétique","cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Un entier $a'$ tel que $a \\times a' \\equiv 1 \\pmod{n}$. Il existe si et seulement si $a$ est premier avec $n$."}]},"exemples":{"items":[{"grade":"T_EXP","content":"$5 \\times 21 = 105 = 4 \\times 26 + 1$, donc $21$ est l’inverse de $5$ modulo $26$."}]},"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre affine","path":"/chiffrement/affine"},"shared_with":[]},{"position":665,"term":"chiffre affine","sense":null,"grade":"T_EXP","tags":["cryptographie","arithmétique"],"definitions":{"items":[{"grade":"T_EXP","content":"Chiffre qui remplace la lettre de rang $x$ par celle de rang $ax + b$ modulo $26$. On ne peut déchiffrer que si $a$ est premier avec $26$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre affine","path":"/chiffrement/affine"},"shared_with":[]},{"position":666,"term":"chiffre de Hill","sense":null,"grade":"T_EXP","tags":["cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Chiffre qui code les lettres par paires, en multipliant le vecteur de leurs rangs par une matrice $2 \\times 2$ inversible modulo $26$."}]},"exemples":null,"history":"Imaginé par le mathématicien américain Lester Hill en 1929.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"Le chiffre de Hill","path":"/chiffrement/hill"},"shared_with":[]},{"position":667,"term":"identité de Bézout","sense":null,"grade":"T_EXP","tags":["entiers","arithmétique","cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Si $d$ est le PGCD de $a$ et $b$, il existe des entiers $u$ et $v$ tels que $au + bv = d$. L’algorithme d’Euclide étendu les calcule."}]},"exemples":{"items":[{"grade":"T_EXP","content":"$1 = -3 \\times 1080 + 463 \\times 7$ : $463$ est l’inverse de $7$ modulo $1080$."}]},"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"RSA de poche","path":"/chiffrement/rsa"},"shared_with":[]},{"position":668,"term":"exponentiation rapide","sense":null,"grade":"T_EXP","tags":["puissances","cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Méthode pour calculer $a^e$ modulo $n$ : on élève au carré encore et encore, et l’on ne multiplie que les carrés qui correspondent aux chiffres $1$ de l’écriture binaire de $e$."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"RSA de poche","path":"/chiffrement/rsa"},"shared_with":[]},{"position":669,"term":"clé publique","sense":null,"grade":"T_EXP","tags":["cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Dans un chiffrement comme RSA, la clé qui sert à chiffrer : elle peut être connue de tous. Seule la clé privée, gardée secrète, permet de déchiffrer."}]},"exemples":null,"history":"L’idée vient de Whitfield Diffie et Martin Hellman (1976) ; RSA (Rivest, Shamir et Adleman, 1977) en est la première réalisation utilisable pour chiffrer.","image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"RSA de poche","path":"/chiffrement/rsa"},"shared_with":[]},{"position":670,"term":"clé privée","sense":null,"grade":"T_EXP","tags":["cryptographie"],"definitions":{"items":[{"grade":"T_EXP","content":"Clé gardée secrète qui permet de déchiffrer les messages chiffrés avec la clé publique correspondante."}]},"exemples":null,"history":null,"image":null,"synonyms":[],"forms":[],"auto_link":true,"derived_from":null,"see_also":{"label":"RSA de poche","path":"/chiffrement/rsa"},"shared_with":[]}]$dictionnaire$::jsonb) as x (
